--
-- Cấu trúc bảng `eb_agent_level`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên cấp bậc',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh nền',
  `one_brokerage` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Tỷ lệ tăng thêm hoa hồng cấp 1',
  `one_brokerage_percent` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tỷ lệ hoa hồng cấp 1',
  `two_brokerage` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Tỷ lệ tăng thêm hoa hồng cấp 2',
  `two_brokerage_percent` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tỷ lệ hoa hồng cấp 2',
  `grade` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Cấp bậc',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `task_total_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Tổng số nhiệm vụ',
  `task_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số nhiệm vụ cần hoàn thành',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng hạng CTV';

