--
-- Cấu trúc bảng `eb_agent_level_task`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level_task` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `level_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID hạng CTV',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên nhiệm vụ',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại nhiệm vụ',
  `number` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng nhiệm vụ giới hạn',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả nhiệm vụ',
  `is_must` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có bắt buộc phải đạt hay không 0: một trong số đó 1: tất cả',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nhiệm vụ hạng CTV';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_agent_level_task_record`
--

CREATE TABLE IF NOT EXISTS `eb_agent_level_task_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `level_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID cấp bậc',
  `task_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID nhiệm vụ',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng ghi nhận CTV hoàn thành nhiệm vụ hạng';

