--
-- Cấu trúc bảng `eb_agreement`
--

CREATE TABLE IF NOT EXISTS `eb_agreement` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại thỏa thuận 1: thỏa thuận thành viên, 2: thỏa thuận đại lý',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'Tên thỏa thuận',
  `content` longtext COMMENT 'Nội dung thỏa thuận',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp giảm dần',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '1: hiển thị 0: không hiển thị',
  `add_time` int(50) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='Thỏa thuận thành viên' ROW_FORMAT=DYNAMIC;

