--
-- Cấu trúc bảng `eb_app_version`
--

CREATE TABLE IF NOT EXISTS `eb_app_version` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `version` varchar(20) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Số phiên bản',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại nền tảng: 1. Android 2. iOS',
  `info` text COMMENT 'Thông tin cập nhật',
  `url` varchar(1000) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Liên kết tải xuống',
  `is_force` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có bắt buộc cập nhật hay không',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bản mới nhất',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng phiên bản APP';

