--
-- Cấu trúc bảng `eb_article`
--

CREATE TABLE IF NOT EXISTS `eb_article` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID quản lý bài viết',
  `cid` varchar(255) NOT NULL DEFAULT '0' COMMENT 'ID danh mục',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề bài viết',
  `author` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tác giả bài viết',
  `image_input` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình ảnh bài viết',
  `synopsis` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn bài viết',
  `share_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề chia sẻ bài viết',
  `share_synopsis` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả chia sẻ bài viết',
  `visit` varchar(255) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Liên kết bài gốc',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thời gian thêm',
  `hide` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có ẩn không',
  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID quản trị viên',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID liên kết sản phẩm',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có phải bài nổi bật không (Mini Program)',
  `is_banner` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có hiển thị ở ảnh trình chiếu không (Mini Program)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý bài viết';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_article_category`
--

CREATE TABLE IF NOT EXISTS `eb_article_category` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID danh mục bài viết',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cấp cha',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề danh mục bài viết',
  `intr` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả danh mục bài viết',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh danh mục bài viết',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '1 đã xóa 0 chưa xóa',
  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thời gian thêm',
  `hidden` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có ẩn không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng danh mục bài viết';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_article_content`
--

CREATE TABLE IF NOT EXISTS `eb_article_content` (
  `nid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID bài viết',
  `content` longtext COMMENT 'Nội dung bài viết',
  UNIQUE KEY `nid` (`nid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nội dung bài viết';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_auxiliary`
--

CREATE TABLE IF NOT EXISTS `eb_auxiliary` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `binding_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID liên kết (bind)',
  `relation_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Liên kết id',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại 0 = hỗ trợ chuyển tiếp CSKH, 1 = hỗ trợ sản phẩm và danh mục, 2 = hỗ trợ phiếu giảm giá và sản phẩm',
  `other` varchar(500) NOT NULL DEFAULT '' COMMENT 'Dữ liệu khác dạng json',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng phụ trợ';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_cache`
--

CREATE TABLE IF NOT EXISTS `eb_cache` (
  `key` varchar(32) NOT NULL DEFAULT '' COMMENT 'Cache key',
  `result` text COMMENT 'Dữ liệu cache',
  `expire_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn 0 = vĩnh viễn',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cache',
  PRIMARY KEY (`key`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng cache WeChat';

