--
-- Cấu trúc bảng `eb_capital_flow`
--

CREATE TABLE IF NOT EXISTS `eb_capital_flow` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `flow_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'ID giao dịch',
  `order_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'Liên kết id',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biệt danh',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Điện thoại',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá trị giao dịch',
  `trading_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại giao dịch',
  `pay_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại thanh toán',
  `mark` varchar(500) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian giao dịch',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng dòng tiền';

