--
-- Cấu trúc bảng `eb_category`
--

CREATE TABLE IF NOT EXISTS `eb_category` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'ID cha',
  `owner_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Người sở hữu, là tất cả',
  `name` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Tên danh mục',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại danh mục 0 = danh mục nhãn, 1 = danh mục cụm từ nhanh',
  `other` text COLLATE utf8_unicode_ci COMMENT 'Tham số khác',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `pid` (`pid`),
  KEY `name` (`name`),
  KEY `is_be` (`owner_id`,`type`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='Danh mục nhãn';

