  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid nhân viên giao hàng',
  `avatar` varchar(250) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện nhân viên giao hàng',
  `nickname` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên nhân viên giao hàng',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '0 ẩn 1 hiện',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nhân viên giao hàng' ROW_FORMAT=DYNAMIC;

