--
-- Cấu trúc bảng `eb_division_agent_apply`
--

CREATE TABLE IF NOT EXISTS `eb_division_agent_apply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `agent_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đại lý',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `phone` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số điện thoại đại lý',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý khu vực',
  `division_invite` int(11) NOT NULL DEFAULT '0' COMMENT 'Mã mời',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Hình ảnh đăng ký',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đăng ký',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đăng ký 0 nộp đơn, 1 đồng ý, 2 từ chối',
  `refusal_reason` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đăng ký đại lý';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_diy`
--

CREATE TABLE IF NOT EXISTS `eb_diy` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `version` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số phiên bản',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên trang',
  `template_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mẫu',
  `value` longtext COMMENT 'Dữ liệu trang',
  `default_value` longtext COMMENT 'Dữ liệu trang mặc định',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã sử dụng',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại trang',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hiển thị trang chủ',
  `is_bg_color` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Màu có được chọn hay không',
  `is_bg_pic` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Ảnh nền có được chọn hay không',
  `color_picker` varchar(50) NOT NULL DEFAULT '' COMMENT 'Màu nền',
  `bg_pic` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ảnh nền',
  `bg_tab_val` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Kiểu ảnh nền',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `order_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Kiểu đơn hàng ở trang cá nhân',
  `my_banner_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Banner trang cá nhân có hiển thị hay không',
  `my_menus_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Kiểu hiển thị “Dịch vụ của tôi” tại trang cá nhân',
  `business_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Kiểu hiển thị “Quản lý cửa hàng” tại trang cá nhân',
  `is_diy` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có tùy chỉnh (DIY) hay không',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Title đầu trang DIY',
  `is_pro` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là phiên bản mới',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng dữ liệu DIY';

