--
-- Cấu trúc bảng `eb_express`
--

CREATE TABLE IF NOT EXISTS `eb_express` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID đơn vị vận chuyển',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên viết tắt đơn vị vận chuyển',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên đầy đủ đơn vị vận chuyển',
  `partner_id` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần tài khoản thanh toán cuối tháng hay không',
  `partner_key` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần mật khẩu thanh toán cuối tháng hay không',
  `net` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần điểm lấy hàng hay không',
  `check_man` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần điền tên nhân viên giao hàng trên vận đơn điện tử hay không',
  `partner_name` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần điền tên tài khoản khách hàng trên vận đơn điện tử hay không',
  `is_code` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có cần điền mã số trên vận đơn điện tử hay không',
  `courier_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên nhân viên chuyển phát',
  `customer_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên tài khoản khách hàng',
  `code_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mã số vận đơn điện tử',
  `account` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tài khoản',
  `key` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mật khẩu',
  `net_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên bưu cục',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hiển thị',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Khả dụng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `code` (`code`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đơn vị vận chuyển';

