  `file_name` varchar(20) DEFAULT '' COMMENT 'Tên file cấu hình',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 bật 0 tắt',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải ngôn ngữ mặc định hay không',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='Loại ngôn ngữ';

