--
-- Cấu trúc bảng `eb_live_anchor`
--

CREATE TABLE IF NOT EXISTS `eb_live_anchor` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên streamer',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh streamer',
  `wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat của streamer',
  `phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng streamer livestream';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_live_goods`
--

CREATE TABLE IF NOT EXISTS `eb_live_goods` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `goods_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm WeChat',
  `audit_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID kiểm duyệt',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Link ảnh sản phẩm',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Link Mini Program của sản phẩm',
  `price_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại giá (1: giá cố định, khi đó đọc trường price; 2: khoảng giá, khi đó trường price là biên trái, trường price2 là biên phải; 3: giá chiết khấu, khi đó trường price là giá gốc, trường price2 là giá hiện tại;)',
  `cost_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá cố định/giá thấp nhất',
  `price2` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá cao nhất',
  `audit_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái kiểm duyệt (0: chưa duyệt, 1: đang duyệt, 2: đã duyệt, 3 duyệt thất bại)',
  `third_part_tag` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1, 2: nghĩa là sản phẩm được thêm qua API, ngược lại là sản phẩm thêm từ bảng điều khiển livestream',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm livestream';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_live_room`
--

CREATE TABLE IF NOT EXISTS `eb_live_room` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `room_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID phòng livestream',
  `name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên phòng livestream',
  `cover_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh nền',
  `share_img` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh chia sẻ',
  `start_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian dự kiến bắt đầu livestream',
  `end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian dự kiến kết thúc livestream',
  `anchor_name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Biệt danh streamer',
  `anchor_wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat của streamer',
  `phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số điện thoại của streamer',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Loại phòng livestream [1: đẩy luồng, 0: livestream bằng điện thoại]',
  `screen_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Màn hình ngang, dọc [1: màn hình ngang, 0: màn hình dọc]',
  `close_like` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có tắt lượt thích không',
  `close_goods` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có tắt kệ hàng không',
  `close_comment` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có tắt bình luận không',
  `error_msg` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do không duyệt',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái kiểm duyệt 0 = chưa duyệt 1 = WeChat đang duyệt 2 = đã duyệt -1 = duyệt không đạt',
  `live_status` smallint(5) UNSIGNED NOT NULL DEFAULT '102' COMMENT 'Trạng thái livestream 101: đang phát, 102: chưa bắt đầu, 103 đã kết thúc, 104 bị cấm phát, 105: tạm dừng, 106: bất thường, 107: đã hết hạn',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `replay_status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái phát lại',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Hiển thị',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`,`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng phòng livestream' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_live_room_goods`
--

CREATE TABLE IF NOT EXISTS `eb_live_room_goods` (
  `live_room_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id phòng livestream',
  `live_goods_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  KEY `broadcast_room_id` (`live_room_id`,`live_goods_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm nhập vào phòng livestream' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_luck_lottery`
--

CREATE TABLE IF NOT EXISTS `eb_luck_lottery` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại quay thưởng 1: ô vuông 9 ô 2: vòng quay lớn 3: ô vuông 9 ô bản nâng cấp 4: lật thẻ may mắn',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên hoạt động quay thưởng',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả hoạt động',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh nền chương trình',
  `factor` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Chi phí quay thưởng: 1: điểm thưởng 2: số dư 3: đặt hàng thanh toán thành công 4: theo dõi 5: đánh giá đơn hàng',
  `factor_num` smallint(5) NOT NULL DEFAULT '10' COMMENT 'Lấy số điều kiện cần để quay thưởng một lần',
  `attends_user` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Người dùng tham gia 1: tất cả 2: một phần',
  `user_level` text COMMENT 'Hạng người dùng tham gia',
  `user_label` text COMMENT 'Nhãn người dùng tham gia',
  `is_svip` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Người dùng tham gia có phải thành viên trả phí không',
  `prize_num` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Số lượng giải thưởng',
  `start_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc',
  `lottery_num_term` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Giới hạn số lần quay thưởng: 1: mỗi ngày 2: mỗi người',
  `lottery_num` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Số lượt quay',
  `spread_num` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Theo dõi (follow) giới thiệu để lấy số lần quay thưởng',
  `is_all_record` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị lịch sử trúng thưởng',
  `is_personal_record` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị lịch sử trúng thưởng cá nhân',
  `is_content` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Quy cách hoạt động có hiển thị không',
  `content` longtext COMMENT 'Nội dung văn bản hoạt động, các loại thỏa thuận quay thưởng',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã sử dụng',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='Danh sách quay thưởng';

--
-- Chuyển lưu dữ liệu trong bảng `eb_luck_lottery`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_luck_lottery_record`
--

CREATE TABLE IF NOT EXISTS `eb_luck_lottery_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `wechat_order_id` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'ID đơn hàng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `lottery_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID chương trình',
  `prize_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID giải thưởng',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại giải thưởng 1: không trúng thưởng 2: điểm thưởng 3: số dư 4: lì xì 5: phiếu giảm giá 6: sản phẩm nội bộ 7: điểm kinh nghiệm hạng 8: hạng người dùng 9: số ngày SVIP',
  `num` DECIMAL(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Điểm thưởng, số dư, số ngày svip, lì xì',
  `is_receive` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã nhận hay chưa',
  `receive_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian nhận',
  `receive_info` text COMMENT 'Địa chỉ nhận hàng, ghi chú, v.v.',
  `is_deliver` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có giao hàng hay không',
  `deliver_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian xử lý giao hàng',
  `deliver_info` text COMMENT 'Mã vận đơn, ghi chú, v.v.',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `channel_type` VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'Nguồn quay thưởng',
  `out_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã đơn phía merchant',
  `transfer_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã chuyển khoản WeChat',
  `state` varchar(32) NOT NULL DEFAULT '' COMMENT 'Trạng thái chứng từ',
  `package_info` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Thông tin package để chuyển đến trang nhận tiền',
  `fail_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`),
  KEY `prize_id` (`prize_id`),
  KEY `lottery_id` (`lottery_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử quay thưởng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_luck_prize`
--

CREATE TABLE IF NOT EXISTS `eb_luck_prize` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính của giải thưởng',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại giải thưởng 1: không trúng thưởng 2: điểm thưởng 3: số dư 4: lì xì 5: phiếu giảm giá 6: sản phẩm nội bộ 7: điểm kinh nghiệm hạng 8: hạng người dùng 9: số ngày SVIP',
  `lottery_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID chương trình quay thưởng',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên giải thưởng',
  `prompt` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lời nhắc khi trúng thưởng',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh giải thưởng',
  `chance` smallint(5) NOT NULL DEFAULT '10' COMMENT 'Cơ số trúng thưởng',
  `percent` DECIMAL(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Tỷ lệ trúng thưởng',
  `total` smallint(5) NOT NULL DEFAULT '1' COMMENT 'Số lượng giải thưởng',
  `coupon_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID phiếu giảm giá liên kết',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm liên kết',
  `unique` varchar(20) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của phân loại sản phẩm liên kết',
  `num` DECIMAL(10,2) NOT NULL DEFAULT '0' COMMENT 'Điểm thưởng, điểm kinh nghiệm, số ngày thành viên',
  `sort` smallint(5) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `lottery_id` (`lottery_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='Danh sách sản phẩm quay thưởng';

--
-- Chuyển lưu dữ liệu trong bảng `eb_luck_prize`
--


