--
-- Cấu trúc bảng `eb_member_card`
--

CREATE TABLE IF NOT EXISTS `eb_member_card` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `card_batch_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID lô thẻ',
  `card_number` varchar(20) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Số thẻ',
  `card_password` char(12) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Mật khẩu',
  `use_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'Người dùng sử dụng',
  `use_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian sử dụng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái thẻ: 0: đóng băng; 1: kích hoạt',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`,`card_batch_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thẻ thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_member_card_batch`
--

CREATE TABLE IF NOT EXISTS `eb_member_card_batch` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `title` varchar(100) NOT NULL DEFAULT '0' COMMENT 'Tên lô',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng thẻ được tạo',
  `use_start_time` int(10) UNSIGNED NOT NULL DEFAULT '7' COMMENT 'Thời gian bắt đầu dùng thử',
  `use_end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc dùng thử',
  `use_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Số ngày trải nghiệm',
  `use_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã sử dụng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiệu lực hay không, kiểm soát toàn bộ thẻ trong lô này 0: không hiệu lực; 1: có hiệu lực',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `qrcode` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn ảnh mã QR',
  `remark` varchar(512) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lô thẻ thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_member_right`
--

CREATE TABLE IF NOT EXISTS `eb_member_right` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `right_type` varchar(100) NOT NULL DEFAULT '' COMMENT 'Loại quyền lợi',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT ' Tên quyền lợi',
  `show_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên quyền lợi hiển thị',
  `image` varchar(200) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Biểu tượng quyền lợi',
  `explain` varchar(1024) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Giới thiệu quyền lợi',
  `number` int(2) NOT NULL DEFAULT '1' COMMENT 'Số quy tắc',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp giảm dần',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0: tắt, 1: bật',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`,`right_type`) USING BTREE,
  KEY `type` (`right_type`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='Quyền lợi thành viên' ROW_FORMAT=DYNAMIC;

--
-- Chuyển lưu dữ liệu trong bảng `eb_member_right`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_member_ship`
--

CREATE TABLE IF NOT EXISTS `eb_member_ship` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `type` varchar(20) NOT NULL DEFAULT 'month' COMMENT 'Loại thành viên month: thẻ tháng; quarter: thẻ quý; year: thẻ năm; ever: vĩnh viễn; free: miễn phí',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'Tên gói thành viên',
  `vip_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thành viên (ngày)',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá gốc',
  `pre_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá sau khi giảm',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Sắp xếp giảm dần',
  `is_del` int(2) NOT NULL DEFAULT '0' COMMENT 'Xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='Loại thành viên' ROW_FORMAT=DYNAMIC;

