--
-- Cấu trúc bảng `eb_message_system`
--

CREATE TABLE IF NOT EXISTS `eb_message_system` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `mark` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã định danh',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `title` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tiêu đề thông báo',
  `content` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nội dung thông báo',
  `data` varchar(5000) NOT NULL DEFAULT '' COMMENT 'Tham số thông báo nội bộ',
  `look` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có xem hay không',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1: người dùng thường, 2: quản trị viên',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thông báo',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Thông báo hệ thống';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_other_order`
--

CREATE TABLE IF NOT EXISTS `eb_other_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Phân biệt \r\n0: nhận miễn phí\r\n1: mua thẻ thành viên \r\n2: dùng mã thẻ để nhận thẻ thành viên',
  `order_id` varchar(32) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng',
  `member_type` varchar(10) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Loại thành viên \r\nThẻ tháng: month\r\nThẻ quý: quarter\r\nThẻ năm: year\r\nVĩnh viễn: ever\r\nMiễn phí: free',
  `code` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số thẻ',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Phương thức thanh toán',
  `paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái thanh toán 0: chưa thanh toán 1: đã thanh toán',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán',
  `member_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá thẻ thành viên',
  `pay_time` int(50) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian mua thành viên',
  `trade_no` varchar(50) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT 'Thanh toán Alipay, mã đơn hàng giao dịch Alipay',
  `channel_type` varchar(10) NOT NULL DEFAULT '' COMMENT 'Kênh thanh toán (OA WeChat, H5, Mini Program)',
  `is_free` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí hay không',
  `is_permanent` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Vĩnh viễn',
  `overdue_time` bigint(20) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn thành viên',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Xóa',
  `vip_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Số ngày hiệu lực thành viên',
  `add_time` int(50) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `money` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá gốc',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử mua thành viên' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_other_order_status`
--

CREATE TABLE IF NOT EXISTS `eb_other_order_status` (
  `oid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng',
  `change_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại thao tác',
  `change_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú thao tác',
  `shop_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại đơn hàng 1: thẻ thành viên',
  `change_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian sửa đơn hàng',
  KEY `oid` (`oid`) USING BTREE,
  KEY `change_type` (`change_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử thao tác đơn hàng' ROW_FORMAT=DYNAMIC;

