--
-- Cấu trúc bảng `eb_out_account`
--

CREATE TABLE IF NOT EXISTS `eb_out_account` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `appid` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tài khoản',
  `appsecret` varchar(100) NOT NULL DEFAULT '' COMMENT 'Khóa bí mật',
  `apppwd` varchar(255) NOT NULL DEFAULT '' COMMENT 'Khóa bí mật dạng văn bản thô',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT 'Mô tả',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `rules` text COMMENT 'Quyền',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `last_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đăng nhập gần nhất',
  `ip` varchar(30) NOT NULL DEFAULT '' COMMENT 'IP',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `push_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có đẩy thông báo hay không',
  `push_account` varchar(255) NOT NULL COMMENT 'Tài khoản push',
  `push_password` varchar(255) NOT NULL COMMENT 'Mật khẩu push',
  `push_token_url` varchar(255) NOT NULL COMMENT 'API lấy token push',
  `user_update_push` varchar(255) NOT NULL COMMENT 'API push người dùng',
  `order_create_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'API push khi tạo đơn hàng',
  `order_pay_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'API push khi thanh toán đơn hàng',
  `refund_create_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'API push khi tạo đơn hậu mãi',
  `refund_cancel_push` varchar(255) NOT NULL DEFAULT '' COMMENT 'API push khi hủy đơn hậu mãi',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Tài khoản API bên ngoài' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_out_interface`
--

CREATE TABLE IF NOT EXISTS `eb_out_interface` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'pid cấp cha',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 menu, 1 API',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên API',
  `describe` text COMMENT 'Mô tả chức năng',
  `method` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại API',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ API',
  `request_params` text COMMENT 'Tham số request',
  `return_params` mediumtext COMMENT 'Tham số trả về',
  `request_example` text COMMENT 'Ví dụ request',
  `return_example` mediumtext COMMENT 'Ví dụ dữ liệu trả về',
  `error_code` text COMMENT 'Trả về lỗi',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COMMENT='API bên ngoài';

