  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID mã QR WeChat',
  `third_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại mã QR',
  `third_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `ticket` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tham số mã QR',
  `expire_seconds` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hiệu lực mã QR',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `add_time` varchar(255) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'URL truy cập WeChat',
  `qrcode_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'URL mã QR WeChat',
  `scan` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần được quét',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Mã QR thuộc nền tảng 1 = Mini Program, 2 = OA WeChat, 3 = H5',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `third_type` (`third_type`,`third_id`) USING BTREE,
  KEY `ticket` (`ticket`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý mã QR WeChat' ROW_FORMAT=COMPACT;

