  `continue_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển sản phẩm tiếp theo',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Cách tính phí',
  `uniqid` varchar(32) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của nhóm',
