--
-- Cấu trúc bảng `eb_sms_record`
--

CREATE TABLE IF NOT EXISTS `eb_sms_record` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Mã lịch sử gửi SMS',
  `uid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tài khoản nền tảng SMS',
  `phone` char(11) NOT NULL DEFAULT '' COMMENT 'Số điện thoại nhận SMS',
  `content` text COMMENT 'Nội dung SMS',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian gửi SMS',
  `add_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'IP khi thêm bản ghi',
  `template` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID mẫu SMS',
  `resultcode` int(6) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Mã trạng thái 100 = thành công, 130 = thất bại, 131 = số không tồn tại, 132 = ngừng hoạt động, 133 = tắt máy, 134 = không có trạng thái',
  `record_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID lịch sử gửi',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử gửi SMS';

