--
-- Cấu trúc bảng `eb_store_advance`
--

CREATE TABLE IF NOT EXISTS `eb_store_activity` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1: Flash sale',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chương trình',
  `start_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Ngày bắt đầu',
  `end_day` int(10) NOT NULL DEFAULT '0' COMMENT 'Ngày kết thúc',
  `time_ids` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhiều ID khung giờ',
  `once_num` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'Số lượng mỗi người được mua mỗi ngày trong thời gian diễn ra chương trình, 0 là không giới hạn',
  `num` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'Giới hạn tổng số lượng mỗi người dùng được mua trong toàn bộ thời gian chương trình, 0 là không giới hạn',
  `is_commission` int(11) NOT NULL DEFAULT '0' COMMENT 'Tham gia chia hoa hồng',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT 'Hiển thị',
  `link_id` int(4) unsigned NOT NULL DEFAULT '0' COMMENT 'ID liên kết',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `start_day` (`start_day`,`end_day`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng chương trình';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_advance`
--

CREATE TABLE IF NOT EXISTS `eb_store_advance` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID sản phẩm đặt trước',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh chính sản phẩm',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề chương trình',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá gốc',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian bắt đầu',
  `stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian kết thúc',
  `add_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian thêm',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Xóa 0 chưa xóa 1 đã xóa',
  `type` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Loại 0 trả đủ 1 đặt cọc',
  `deposit` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền đặt cọc',
  `pay_start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian bắt đầu thanh toán số tiền còn lại',
  `pay_stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian kết thúc thanh toán số tiền còn lại',
  `deliver_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Sau khi thanh toán bao nhiêu ngày thì giao hàng',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Mua tối đa bao nhiêu sản phẩm',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mẫu phí vận chuyển',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số lượng giới hạn mua',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng số lượng giới hạn mua',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua mỗi lần',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm đặt trước';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_bargain`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID sản phẩm săn giảm giá',
  `product_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm liên kết',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chương trình săn giảm giá',
  `image` varchar(150) NOT NULL DEFAULT '' COMMENT 'Ảnh hoạt động săn giảm giá',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `stock` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `sales` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu (banner) sản phẩm săn giảm giá',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu săn giảm giá',
  `stop_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc săn giảm giá',
  `store_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm săn giảm giá',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền săn giảm giá',
  `min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá thấp nhất sản phẩm săn giảm giá',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Số lượng sản phẩm săn giảm giá có thể mua',
  `bargain_max_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền tối đa mỗi lần người dùng săn giảm giá',
  `bargain_min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền tối thiểu mỗi lần người dùng săn giảm giá',
  `bargain_num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Số lần người dùng giúp giảm giá',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái săn giảm giá 0 (đến thời gian săn giảm giá không tự động mở) 1 (đến thời gian săn giảm giá tự động mở)',
  `give_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Hoàn lại bao nhiêu điểm thưởng',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giới thiệu chương trình săn giảm giá',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có đề xuất hay không 0 không đề xuất 1 đề xuất',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có xóa hay không 0 chưa xóa 1 đã xóa',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Có miễn phí vận chuyển hay không 0 không miễn phí 1 miễn phí',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `rule` longtext COMMENT 'Quy tắc săn giảm giá',
  `look` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt xem sản phẩm săn giảm giá',
  `share` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt chia sẻ sản phẩm săn giảm giá',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mẫu phí vận chuyển',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trọng lượng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Thể tích',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số lượng giới hạn mua',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng số lượng giới hạn',
  `people_num` int(11) NOT NULL DEFAULT '1' COMMENT 'Số lần người dùng giúp giảm giá',
  `logistics` varchar(11) NOT NULL DEFAULT '1,2' COMMENT 'Hình thức vận chuyển',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Form tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có trả hoa hồng không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng săn giảm giá';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_bargain_user`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain_user` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bảng người dùng tham gia săn giảm giá',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm săn giảm giá',
  `bargain_price_min` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá thấp nhất khi săn giảm giá',
  `bargain_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền săn giảm giá',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền đã giảm được',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái 1 đang tham gia 2 hoạt động kết thúc, tham gia thất bại 3 hoạt động kết thúc, tham gia thành công',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian tham gia',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã hủy chưa',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng người dùng tham gia săn giảm giá';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_bargain_user_help`
--

CREATE TABLE IF NOT EXISTS `eb_store_bargain_user_help` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bảng người dùng giúp săn giảm giá',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng giúp',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm săn giảm giá',
  `bargain_user_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID bảng người dùng tham gia săn giảm giá',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giúp giảm được bao nhiêu tiền',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải tự mình săn giảm giá hay không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng người dùng giúp săn giảm giá';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_cart`
--

CREATE TABLE IF NOT EXISTS `eb_store_cart` (
  `id` bigint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bảng giỏ hàng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `product_attr_unique` varchar(16) NOT NULL DEFAULT '' COMMENT 'Thuộc tính sản phẩm',
  `cart_num` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng sản phẩm',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = chưa mua 1 = đã mua',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải mua ngay hay không',
  `combination_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID mua chung',
  `seckill_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm flash sale',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID săn giảm giá',
  `advance_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm đặt trước',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái sản phẩm trong giỏ hàng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`product_id`) USING BTREE,
  KEY `uid` (`uid`,`is_pay`) USING BTREE,
  KEY `uid_2` (`uid`,`is_del`) USING BTREE,
  KEY `uid_3` (`uid`,`is_new`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giỏ hàng' ROW_FORMAT=COMPACT;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_category`
--

CREATE TABLE IF NOT EXISTS `eb_store_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID bảng danh mục sản phẩm',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cha',
  `cate_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên danh mục',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `pic` varchar(128) NOT NULL DEFAULT '' COMMENT 'Biểu tượng',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có đề xuất không',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `big_pic` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh lớn danh mục',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `is_base` (`is_show`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng danh mục sản phẩm';

