--
-- Cấu trúc bảng `eb_store_combination`
--

CREATE TABLE IF NOT EXISTS `eb_store_combination` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đề xuất',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề chương trình',
  `attr` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thuộc tính hoạt động',
  `people` int(2) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số người tham gia nhóm',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `add_time` varchar(128) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_host` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Gợi ý',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `combination` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Mua chung',
  `mer_use` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cửa hàng có khả dụng hay không 1 khả dụng 0 không khả dụng',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí vận chuyển hay không 1 có 0 không',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu mua chung',
  `stop_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc mua chung',
  `effective_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hiệu lực đơn hàng mua chung',
  `cost` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Giá vốn sản phẩm mua chung',
  `browse` int(11) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `unit_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mẫu phí vận chuyển',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trọng lượng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Thể tích',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua mỗi lần',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng có thể mua mỗi đơn hàng',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số lượng giới hạn mua',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng số lượng giới hạn',
  `virtual` int(11) NOT NULL DEFAULT '100' COMMENT 'Tỷ lệ phần trăm ghép nhóm ảo',
  `logistics` varchar(11) NOT NULL DEFAULT '1,2' COMMENT 'Hình thức vận chuyển',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Form tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Mua chung có trả hoa hồng hay không',
  `head_commission` int(11) NOT NULL DEFAULT '0' COMMENT 'Tỷ lệ hoa hồng trưởng nhóm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm mua chung';

