--
-- Cấu trúc bảng `eb_store_coupon_issue`
--

CREATE TABLE IF NOT EXISTS `eb_store_coupon_issue` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `cid` int(10) NOT NULL DEFAULT '0' COMMENT 'ID phiếu giảm giá',
  `coupon_title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên phiếu giảm giá',
  `start_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu nhận phiếu giảm giá',
  `end_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc nhận phiếu giảm giá',
  `total_count` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá được nhận',
  `remain_count` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá còn lại có thể nhận',
  `receive_limit` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng phiếu giảm giá mỗi người được nhận',
  `is_permanent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải không giới hạn số lượng hay không',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 bình thường 0 chưa mở -1 đã hết hiệu lực',
  `is_give_subscribe` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có tặng khi theo dõi lần đầu hay không 0 - không (mặc định) 1 - có',
  `is_full_give` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có tặng khi đạt mức đơn tối thiểu hay không 0 - không (mặc định) 1 - có',
  `full_reduction` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Chi tiêu đạt bao nhiêu thì tặng phiếu giảm giá',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm phiếu giảm giá',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên phiếu giảm giá',
  `integral` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số điểm thưởng tiêu tốn để đổi',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Mệnh giá phiếu giảm giá được đổi',
  `use_min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Chi tiêu tối thiểu bao nhiêu thì được dùng phiếu giảm giá',
  `coupon_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời hạn hiệu lực phiếu giảm giá (đơn vị: ngày)',
  `product_id` varchar(2000) NOT NULL DEFAULT '' COMMENT 'ID sản phẩm áp dụng',
  `category_id` varchar(2000) NOT NULL DEFAULT '' COMMENT 'ID danh mục',
  `type` tinyint(2) NOT NULL DEFAULT '0' COMMENT 'Loại phiếu giảm giá 0 - dùng chung 1 - phiếu theo danh mục 2 - phiếu theo sản phẩm',
  `receive_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 tự nhận, 2 phiếu người mới, 3 phiếu tặng, 4 phiếu thành viên',
  `start_use_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu sử dụng phiếu giảm giá',
  `end_use_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc sử dụng phiếu giảm giá',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cid` (`cid`) USING BTREE,
  KEY `start_time` (`start_time`,`end_time`) USING BTREE,
  KEY `remain_count` (`remain_count`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `coupon_time` (`coupon_time`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nhận phiếu giảm giá ở front-end' ROW_FORMAT=COMPACT;

