--
-- Cấu trúc bảng `eb_store_coupon_user`
--

CREATE TABLE IF NOT EXISTS `eb_store_coupon_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID lịch sử phát phiếu giảm giá',
  `cid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID mục được đổi',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người dùng sở hữu phiếu giảm giá',
  `coupon_title` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên phiếu giảm giá',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Mệnh giá phiếu giảm giá',
  `use_min_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Chi tiêu tối thiểu bao nhiêu thì được dùng phiếu giảm giá',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian tạo phiếu giảm giá',
  `start_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu phiếu giảm giá',
  `end_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc phiếu giảm giá',
  `use_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian sử dụng',
  `type` varchar(32) NOT NULL DEFAULT 'send' COMMENT 'Cách nhận',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái (0: chưa sử dụng, 1: đã sử dụng, 2: đã hết hạn)',
  `is_fail` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái hiệu lực',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cid` (`cid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `end_time` (`end_time`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_fail` (`is_fail`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử phát phiếu giảm giá';

