--
-- Cấu trúc bảng `eb_store_integral`
--

CREATE TABLE IF NOT EXISTS `eb_store_integral` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID sản phẩm đổi điểm',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề chương trình',
  `price` int(10) NOT NULL DEFAULT '0' COMMENT 'Điểm quy đổi',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `add_time` varchar(128) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_host` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Gợi ý',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái sản phẩm',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Xóa',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Tối đa đổi được bao nhiêu điểm',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số lượng giới hạn mua',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua mỗi lần',
  `quota_show` int(11) NOT NULL DEFAULT '0' COMMENT 'Hiển thị giới hạn mua',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm đổi điểm';

