--
-- Cấu trúc bảng `eb_store_integral_order`
--

CREATE TABLE IF NOT EXISTS `eb_store_integral_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID đơn hàng',
  `order_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Mã đơn hàng',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Họ tên người dùng',
  `user_phone` varchar(18) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người dùng',
  `user_address` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `store_name` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `suk` varchar(128) NOT NULL DEFAULT '' COMMENT 'Quy cách',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số sản phẩm trong đơn hàng',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Đơn giá',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Tổng điểm thưởng',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1: chờ giao hàng; 2: chờ nhận hàng; 3: đã hoàn thành;',
  `delivery_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị vận chuyển/họ tên người giao hàng',
  `delivery_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã đơn vị vận chuyển',
  `delivery_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Hình thức giao hàng',
  `delivery_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Mã vận đơn/số điện thoại',
  `fictitious_content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung giao hàng ảo',
  `delivery_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhân viên giao hàng',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `remark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú của quản trị viên',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `is_mer_check` tinyint(3) UNSIGNED NOT NULL DEFAULT '0',
  `is_remind` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thông báo nhắc nhở',
  `is_system_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trang quản trị có xóa hay không',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Định danh thiết bị/nền tảng truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người dùng',
  `express_dump` varchar(502) NOT NULL DEFAULT '' COMMENT 'Thông tin in vận đơn của đơn hàng',
  `verify_code` varchar(125) NOT NULL DEFAULT '' COMMENT 'Mã xác nhận',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đơn hàng đổi điểm';

