--
-- Cấu trúc bảng `eb_store_order`
--

CREATE TABLE IF NOT EXISTS `eb_store_order` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID đơn hàng',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng cha',
  `order_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Mã đơn hàng',
  `trade_no` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mã đơn thanh toán',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Họ tên người dùng',
  `user_phone` varchar(18) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người dùng',
  `user_address` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `cart_id` text COMMENT 'ID giỏ hàng',
  `freight_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `total_num` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số sản phẩm trong đơn hàng',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Tổng giá đơn hàng',
  `total_postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán thực tế',
  `pay_postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển đã thanh toán',
  `deduction_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền khấu trừ',
  `coupon_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID phiếu giảm giá',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền phiếu giảm giá',
  `paid` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái thanh toán',
  `pay_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thanh toán',
  `pay_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Phương thức thanh toán',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đơn hàng (-1: yêu cầu hoàn tiền, -2: trả hàng thành công, 0: chờ giao hàng; 1: chờ nhận hàng; 2: đã nhận hàng; 3: chờ đánh giá; -1: đã hoàn tiền)',
  `is_stock_up` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có đang chuẩn bị hàng hay không',
  `refund_status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chưa hoàn tiền, 1 = đang yêu cầu, 2 = đã hoàn tiền',
  `refund_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại yêu cầu hoàn tiền',
  `refund_express` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã vận đơn trả hàng',
  `refund_express_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị vận chuyển trả hàng',
  `refund_reason_wap_img` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Hình ảnh hoàn tiền',
  `refund_reason_wap_explain` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả hoàn tiền của người dùng',
  `refund_reason_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hoàn tiền',
  `refund_reason_wap` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do hoàn tiền phía khách hàng',
  `refund_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do không hoàn tiền',
  `refund_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn',
  `delivery_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị vận chuyển/họ tên người giao hàng',
  `delivery_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã đơn vị vận chuyển',
  `delivery_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Hình thức giao hàng',
  `delivery_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Mã vận đơn/số điện thoại',
  `kuaidi_label` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh mã vận đơn',
  `kuaidi_task_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'ID nhiệm vụ vận đơn',
  `kuaidi_order_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng của vận đơn',
  `fictitious_content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung giao hàng ảo',
  `delivery_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhân viên giao hàng',
  `gain_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Điểm thưởng nhận được khi mua hàng',
  `use_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Điểm thưởng đã dùng',
  `back_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số điểm thưởng đã hoàn lại cho người dùng',
  `spread_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người giới thiệu',
  `spread_two_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người giới thiệu của người giới thiệu',
  `one_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền trả hoa hồng cấp 1',
  `two_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền trả hoa hồng cấp 2',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `is_cancel` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã hủy chưa',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'ID duy nhất (mã hóa md5) tương tự id',
  `remark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú của quản trị viên',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `is_mer_check` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cửa hàng tải lên',
  `combination_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm mua chung, 0 là sản phẩm thường',
  `pink_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID mua chung, 0 là không có mua chung',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `seckill_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm flash sale',
  `bargain_id` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID săn giảm giá',
  `advance_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm đặt trước',
  `verify_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'Mã xác nhận',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cửa hàng',
  `shipping_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Phương thức giao hàng 1=chuyển phát, 2=nhận tại cửa hàng',
  `clerk_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhân viên cửa hàng',
  `is_channel` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Kênh thanh toán (0=OA WeChat, 1=WeChat Mini Program)',
  `is_remind` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thông báo nhắc nhở',
  `is_system_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trang quản trị có xóa hay không',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Định danh thiết bị/nền tảng truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người dùng',
  `express_dump` varchar(502) NOT NULL DEFAULT '' COMMENT 'Thông tin in vận đơn của đơn hàng',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm ảo',
  `virtual_info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thông tin sản phẩm ảo',
  `pay_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng thanh toán',
  `custom_form` text COMMENT 'Form tùy chỉnh',
  `staff_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhân viên',
  `agent_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý khu vực',
  `staff_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng trả cho nhân viên',
  `agent_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng trả cho đại lý',
  `division_brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trả hoa hồng đại lý khu vực',
  `is_gift` int(1) NOT NULL DEFAULT '0' COMMENT 'Là đơn quà tặng',
  `gift_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Phụ phí quà tặng',
  `gift_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'Người dùng nhận quà (uid)',
  `gift_mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lời nhắn quà tặng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  UNIQUE KEY `unique` (`unique`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pay_price` (`pay_price`) USING BTREE,
  KEY `paid` (`paid`) USING BTREE,
  KEY `pay_time` (`pay_time`) USING BTREE,
  KEY `pay_type` (`pay_type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `coupon_id` (`coupon_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đơn hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_order_cart_info`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_cart_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `oid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `cart_id` varchar(50) NOT NULL DEFAULT '0' COMMENT 'ID giỏ hàng',
  `product_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `old_cart_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'cart_id trước khi tách đơn',
  `cart_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng',
  `refund_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng hoàn tiền',
  `surplus_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng còn lại sau khi tách',
  `split_status` int(1) NOT NULL DEFAULT '0' COMMENT '0: chưa tách 1: vẫn có thể tách 2: đã tách xong',
  `cart_info` text COMMENT 'Thông tin chi tiết hàng đã mua',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'ID duy nhất',
  PRIMARY KEY (`id`),
  UNIQUE KEY `oid` (`oid`,`unique`) USING BTREE,
  KEY `cart_id` (`cart_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng chi tiết mua hàng của đơn hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_order_economize`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_economize` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID đơn hàng',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng',
  `uid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `order_type` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT '1' COMMENT 'Phương thức giao hàng 1 = đơn hàng sản phẩm, 2 = đơn hàng ngoại tuyến',
  `pay_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán thực tế',
  `postage_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giảm phí vận chuyển',
  `member_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền ưu đãi thành viên',
  `offline_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giảm ngoại tuyến',
  `coupon_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền giảm từ phiếu giảm giá',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian tạo',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái',
  PRIMARY KEY (`id`,`order_id`,`uid`) USING BTREE,
  UNIQUE KEY `order_id_2` (`order_id`,`uid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pay_price` (`pay_price`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng tiền tiết kiệm của người dùng';

