--
-- Cấu trúc bảng `eb_store_order_invoice`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_invoice` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `category` varchar(10) NOT NULL DEFAULT 'order' COMMENT 'Danh mục xuất hóa đơn order: đơn hàng',
  `order_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng',
  `invoice_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID hóa đơn',
  `header_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại tiêu đề hóa đơn',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại hóa đơn',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên (thông tin xuất hóa đơn)',
  `duty_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã số thuế',
  `drawer_phone` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người yêu cầu xuất hóa đơn',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT 'Email nhận hóa đơn',
  `tell` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại đăng ký',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ đăng ký',
  `bank` varchar(50) NOT NULL DEFAULT '' COMMENT 'Ngân hàng mở tài khoản',
  `card_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số thẻ ngân hàng',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã thanh toán',
  `is_refund` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đơn hàng có hoàn tiền hay không',
  `is_invoice` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xuất hóa đơn chưa',
  `invoice_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số hóa đơn',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `invoice_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian xuất hóa đơn',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `unique_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất',
  `invoice_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số hóa đơn',
  `invoice_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại hóa đơn',
  `invoice_serial_number` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số seri hóa đơn',
  `red_invoice_num` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã hóa đơn đỏ (hóa đơn điều chỉnh giảm)',
  `is_del` tinyint(1) DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng hóa đơn đơn hàng';

