--
-- Cấu trúc bảng `eb_store_order_refund`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_refund` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `store_order_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID bảng đơn hàng',
  `store_id` int(10) NOT NULL DEFAULT '0' COMMENT 'ID cửa hàng',
  `order_id` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'UID người dùng',
  `refund_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại yêu cầu hoàn tiền',
  `refund_num` int(5) NOT NULL DEFAULT '0' COMMENT 'Số lượng hoàn tiền',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn',
  `refunded_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền đã hoàn',
  `refund_phone` varchar(32) NOT NULL DEFAULT '' COMMENT 'Số điện thoại liên hệ hoàn tiền',
  `refund_express` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mã vận đơn trả hàng',
  `refund_express_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị vận chuyển trả hàng',
  `refund_explain` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả hoàn tiền của người dùng',
  `refund_img` text COMMENT 'Hình ảnh hoàn tiền',
  `refund_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do không hoàn tiền',
  `refuse_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `refunded_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian xử lý',
  `cart_info` longtext COMMENT 'Thông tin sản phẩm hoàn tiền',
  `is_cancel` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Người dùng đã hủy chưa',
  `is_pink_cancel` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có tự động hủy do mua chung không',
  `is_del` tinyint(1) DEFAULT '0' COMMENT 'Hủy yêu cầu',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian yêu cầu hoàn tiền',
  `is_system_del` tinyint(1) DEFAULT '0' COMMENT 'Hệ thống xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đơn hàng hoàn tiền';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_order_status`
--

CREATE TABLE IF NOT EXISTS `eb_store_order_status` (
  `oid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng',
  `change_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại thao tác',
  `change_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú thao tác',
  `change_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thao tác',
  KEY `oid` (`oid`) USING BTREE,
  KEY `change_type` (`change_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử thao tác đơn hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_pink`
--

CREATE TABLE IF NOT EXISTS `eb_store_pink` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Biệt danh người dùng',
  `avatar` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện người dùng',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'ID đơn hàng, tạo ra',
  `order_id_key` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng, database',
  `total_num` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lượng sản phẩm mua',
  `total_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Tổng số tiền mua',
  `cid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm mua chung',
  `pid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `people` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tổng số người ghép nhóm',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Đơn giá sản phẩm mua chung',
  `add_time` varchar(24) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu',
  `stop_time` varchar(24) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc',
  `k_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID trưởng nhóm, 0 là trưởng nhóm',
  `is_tpl` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có gửi tin nhắn mẫu hay không 0 chưa gửi 1 đã gửi',
  `is_refund` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có hoàn tiền hay không 0 chưa hoàn tiền 1 đã hoàn tiền',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái 1 đang diễn ra 2 đã hoàn thành 3 chưa hoàn thành',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải mua chung ảo hay không',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng mua chung';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product`
--

CREATE TABLE IF NOT EXISTS `eb_store_product` (
  `id` mediumint(11) NOT NULL AUTO_INCREMENT COMMENT 'id sản phẩm',
  `mer_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID cửa hàng (0 là do quản trị viên tổng tạo, khác 0 là do trang quản trị cửa hàng tạo)',
  `image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Hình ảnh sản phẩm',
  `recommend_image` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ảnh đề xuất',
  `slider_image` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu',
  `store_name` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên sản phẩm',
  `store_info` varchar(256) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn sản phẩm',
  `keyword` varchar(256) NOT NULL DEFAULT '' COMMENT 'Từ khóa',
  `bar_code` varchar(15) NOT NULL DEFAULT '' COMMENT 'Mã vạch sản phẩm (mã 1 chiều)',
  `cate_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'ID danh mục',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá sản phẩm',
  `vip_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá thành viên',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá thị trường',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `unit_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `sort` smallint(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `sales` mediumint(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `stock` mediumint(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `is_show` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái (0: chưa lên kệ, 1: đã lên kệ)',
  `is_hot` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là hàng bán chạy',
  `is_benefit` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là sản phẩm khuyến mãi',
  `is_best` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là sản phẩm nổi bật',
  `is_new` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là sản phẩm mới',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Sản phẩm có phải là sản phẩm ảo hay không',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm ảo',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí vận chuyển',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `mer_use` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cửa hàng có làm đại lý hay không 0 không thể làm đại lý 1 có thể làm đại lý',
  `give_integral` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Điểm thưởng nhận được',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `is_seckill` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái flash sale 0 chưa mở 1 đã mở',
  `is_bargain` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Trạng thái săn giảm giá 0 chưa mở 1 mở',
  `is_good` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Là sản phẩm chất lượng được đề xuất',
  `is_sub` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có tính hoa hồng riêng hay không',
  `is_vip` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có bật giá thành viên hay không',
  `ficti` mediumint(11) NOT NULL DEFAULT '0' COMMENT 'Lượt bán ảo',
  `browse` int(11) NOT NULL DEFAULT '0' COMMENT 'Lượt xem',
  `code_path` varchar(64) NOT NULL DEFAULT '' COMMENT 'Địa chỉ mã QR sản phẩm (poster Mini Program của người dùng)',
  `soure_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại Taobao/JD/1688',
  `video_link` varchar(500) NOT NULL DEFAULT '' COMMENT 'Link video ảnh chính',
  `temp_id` int(11) NOT NULL DEFAULT '1' COMMENT 'ID mẫu phí vận chuyển',
  `spec_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Phân loại 0 đơn 1 đa',
  `activity` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thứ tự hiển thị hoạt động 1 = flash sale, 2 = săn giảm giá, 3 = mua chung',
  `spu` char(13) NOT NULL DEFAULT '' COMMENT 'SPU sản phẩm',
  `label_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'ID nhãn',
  `command_word` varchar(255) NOT NULL DEFAULT '' COMMENT 'Sao chép mã chia sẻ',
  `recommend_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID sản phẩm đề xuất',
  `vip_product` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải sản phẩm dành riêng cho thành viên hay không',
  `vip_product_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0: chỉ thành viên trả phí được xem, 1: chỉ thành viên trả phí được mua',
  `presale` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải sản phẩm đặt trước hay không',
  `presale_start_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian bắt đầu đặt trước',
  `presale_end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc đặt trước',
  `presale_day` int(11) NOT NULL DEFAULT '0' COMMENT 'Sau khi kết thúc đặt trước bao nhiêu ngày thì giao hàng',
  `logistics` varchar(10) NOT NULL DEFAULT '1,2' COMMENT 'Hình thức vận chuyển',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Form tùy chỉnh',
  `is_limit` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có bật giới hạn mua hay không',
  `limit_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại giới hạn mua 1 giới hạn theo lần 2 giới hạn vĩnh viễn',
  `limit_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng giới hạn mua',
  `min_qty` int(11) NOT NULL DEFAULT '1' COMMENT 'Số lượng mua tối thiểu',
  `default_sku` varchar(255) NOT NULL DEFAULT '' COMMENT 'Phân loại mặc định',
  `params_list` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Thông số sản phẩm',
  `label_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhãn sản phẩm',
  `protection_list` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đảm bảo sản phẩm',
  `is_gift` int(1) NOT NULL DEFAULT '0' COMMENT 'Là quà tặng',
  `gift_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Phụ phí quà tặng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cate_id` (`cate_id`) USING BTREE,
  KEY `is_hot` (`is_hot`) USING BTREE,
  KEY `is_benefit` (`is_benefit`) USING BTREE,
  KEY `is_best` (`is_best`) USING BTREE,
  KEY `is_new` (`is_new`) USING BTREE,
  KEY `toggle_on_sale, is_del` (`is_del`) USING BTREE,
  KEY `price` (`price`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `sales` (`sales`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `is_postage` (`is_postage`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm';

