CREATE TABLE IF NOT EXISTS `eb_store_product_attr` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `attr_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên thuộc tính',
  `attr_values` longtext COMMENT 'Giá trị thuộc tính',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0 = sản phẩm, 1 = flash sale, 2 = săn giảm giá, 3 = mua chung',
  PRIMARY KEY (`id`),
  KEY `store_id` (`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thuộc tính sản phẩm';

