  `result` longtext COMMENT 'Tham số thuộc tính sản phẩm',
  `change_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian sửa gần nhất',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0 = sản phẩm, 1 = flash sale, 2 = săn giảm giá, 3 = mua chung',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`) USING BTREE
