--
-- Cấu trúc bảng `eb_store_product_attr_value`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_attr_value` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `suk` varchar(128) NOT NULL DEFAULT '' COMMENT 'Giá trị chỉ mục thuộc tính sản phẩm (attr_value|attr_value[|....])',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho tương ứng với thuộc tính',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền của thuộc tính',
  `image` varchar(128) NOT NULL DEFAULT '' COMMENT 'Hình ảnh',
  `unique` char(8) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `bar_code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã vạch sản phẩm',
  `bar_code_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã vạch',
  `ot_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá gốc',
  `vip_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá dành riêng cho thành viên',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Trọng lượng',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Thể tích',
  `brokerage` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng cấp 1',
  `brokerage_two` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng cấp 2',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại hoạt động 0 = sản phẩm, 1 = flash sale, 2 = săn giảm giá, 3 = mua chung',
  `quota` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng giới hạn mua của hoạt động',
  `quota_show` int(11) NOT NULL DEFAULT '0' COMMENT 'Hiển thị số lượng giới hạn mua của hoạt động',
  `is_virtual` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải sản phẩm ảo không',
  `coupon_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID phiếu giảm giá',
  `disk_info` text COMMENT 'Nội dung thông tin ảo',
  `is_show` int(1) NOT NULL DEFAULT '1' COMMENT 'Hiển thị',
  `is_default_select` int(1) NOT NULL DEFAULT '0' COMMENT 'Có phải phân loại mặc định hay không',
  PRIMARY KEY (`id`),
  KEY `unique` (`unique`,`suk`) USING BTREE,
  KEY `store_id` (`product_id`,`suk`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giá trị thuộc tính sản phẩm';

