  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_del` int(11) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
