--
-- Cấu trúc bảng `eb_store_product_log`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `type` enum('visit','cart','order','pay','collect','refund') NOT NULL COMMENT 'Loại',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `visit_num` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có xem hay không',
  `cart_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng thêm vào giỏ hàng',
  `order_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng đặt hàng',
  `pay_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng thanh toán',
  `pay_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền thanh toán',
  `cost_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn sản phẩm',
  `pay_uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người dùng thanh toán',
  `refund_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng hoàn',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn',
  `collect_num` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Yêu thích',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Thống kê sản phẩm';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product_param`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_param` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên thông số',
  `value` text COMMENT 'Nội dung thông số',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_del` int(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT 'Trạng thái thông số',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thông số sản phẩm';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product_protection`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_protection` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề',
  `content` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Nội dung',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biểu tượng',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng sử dụng',
  `status` int(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_del` int(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đảm bảo sản phẩm';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product_relation`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_relation` (
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại (yêu thích (collect), thích (like))',
  `category` varchar(32) NOT NULL DEFAULT '' COMMENT 'Sản phẩm thuộc một loại nào đó (sản phẩm thường, sản phẩm flash sale)',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  UNIQUE KEY `uid` (`uid`,`product_id`,`type`,`category`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thích và yêu thích sản phẩm';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product_reply`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_reply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID đánh giá',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `oid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đơn hàng',
  `unique` char(32) NOT NULL DEFAULT '' COMMENT 'ID duy nhất',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `reply_type` varchar(32) NOT NULL DEFAULT 'product' COMMENT 'Một loại sản phẩm nào đó (sản phẩm thường, sản phẩm flash sale)',
  `product_score` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Điểm sản phẩm',
  `service_score` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Điểm dịch vụ',
  `comment` varchar(512) NOT NULL DEFAULT '' COMMENT 'Nội dung đánh giá',
  `pics` text COMMENT 'Hình ảnh đánh giá',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đánh giá',
  `merchant_reply_content` varchar(300) NOT NULL DEFAULT '' COMMENT 'Nội dung phản hồi của quản trị viên',
  `merchant_reply_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian phản hồi của quản trị viên',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 chưa xóa 1 đã xóa',
  `is_reply` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 chưa phản hồi 1 đã phản hồi',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện người dùng',
  `suk` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên quy cách',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái bình luận',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id_2` (`oid`,`unique`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `parent_id` (`reply_type`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `product_score` (`product_score`) USING BTREE,
  KEY `service_score` (`service_score`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng bình luận';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_product_rule`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_rule` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `rule_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên quy cách',
  `rule_value` text COMMENT 'Giá trị phân loại',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giá trị quy tắc sản phẩm (phân loại)';

