-- Cấu trúc bảng `eb_store_product_virtual`
--

CREATE TABLE IF NOT EXISTS `eb_store_product_virtual` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `attr_unique` varchar(20) NOT NULL DEFAULT '' COMMENT 'Phân loại sản phẩm tương ứng',
  `card_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số thẻ (mã thẻ)',
  `card_pwd` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mật khẩu thẻ',
  `card_unique` varchar(32) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của thẻ ảo',
  `order_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID đơn hàng mua',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người mua',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng mã thẻ sản phẩm ảo';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_seckill`
--

CREATE TABLE IF NOT EXISTS `eb_store_seckill` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bảng sản phẩm flash sale',
  `activity_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID chương trình',
  `product_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id sản phẩm',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đề xuất',
  `images` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Ảnh trình chiếu',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tiêu đề chương trình',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn',
  `price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá',
  `cost` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá vốn',
  `ot_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Giá gốc',
  `give_integral` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Hoàn lại bao nhiêu điểm thưởng',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `stock` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Tồn kho',
  `sales` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Lượt bán',
  `unit_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Tên đơn vị',
  `postage` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí vận chuyển',
  `start_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian bắt đầu',
  `stop_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian kết thúc',
  `add_time` varchar(128) NOT NULL DEFAULT '' COMMENT 'Thời gian thêm',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái sản phẩm',
  `is_postage` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có miễn phí vận chuyển',
  `is_hot` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Gợi ý nổi bật',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Xóa 0 chưa xóa 1 đã xóa',
  `num` int(11) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Tối đa flash sale được bao nhiêu sản phẩm',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Hiện',
  `time_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID khung giờ',
  `temp_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mẫu phí vận chuyển',
  `weight` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Khối lượng sản phẩm',
  `volume` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Thể tích sản phẩm',
  `quota` int(10) NOT NULL DEFAULT '0' COMMENT 'Tổng số lượng giới hạn mua',
  `quota_show` int(10) NOT NULL DEFAULT '0' COMMENT 'Hiển thị tổng số lượng giới hạn mua',
  `once_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lượng mua mỗi lần',
  `logistics` varchar(10) NOT NULL DEFAULT '1,2' COMMENT 'Loại vận chuyển',
  `freight` tinyint(1) NOT NULL DEFAULT '2' COMMENT 'Cài đặt phí vận chuyển',
  `custom_form` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Form tùy chỉnh',
  `virtual_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại sản phẩm',
  `is_commission` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có trả hoa hồng không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `start_time` (`start_time`,`stop_time`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `is_hot` (`is_hot`) USING BTREE,
  KEY `is_show` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `is_postage` (`is_postage`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng sản phẩm flash sale';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_seckill_time`
--

CREATE TABLE IF NOT EXISTS `eb_store_seckill_time` (
