--
-- Cấu trúc bảng `eb_store_service`
--

CREATE TABLE IF NOT EXISTS `eb_store_service` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID nhân viên CSKH',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid CSKH',
  `online` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có đang online không',
  `account` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tài khoản',
  `password` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mật khẩu',
  `avatar` varchar(250) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện CSKH',
  `nickname` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên đại lý',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số điện thoại CSKH',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '0 ẩn 1 hiện',
  `notify` int(2) NOT NULL DEFAULT '0' COMMENT 'Thông báo đơn hàng 1=bật, 0=tắt',
  `customer` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiển thị quản lý thống kê hay không',
  `uniqid` varchar(35) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng CSKH';

