--
-- Cấu trúc bảng `eb_store_service_feedback`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_feedback` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'UID người dùng',
  `rela_name` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Họ tên',
  `phone` varchar(30) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Điện thoại',
  `content` varchar(500) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Nội dung phản hồi',
  `make` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái 0 = chưa xem, 1 = đã xem',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Phản hồi';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_service_log`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID bảng lịch sử hội thoại CSKH với người dùng',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `msn` text COMMENT 'Nội dung tin nhắn',
  `uid` int(11) NOT NULL DEFAULT '1' COMMENT 'uid người gửi',
  `to_uid` int(11) NOT NULL DEFAULT '1' COMMENT 'uid người nhận',
  `is_tourist` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = chế độ khách, 0 = không phải khách',
  `time_node` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Mốc thời gian',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian gửi',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã đọc hay chưa (0: chưa; 1: đã;)',
  `remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã từng nhắc hay chưa',
  `msn_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Loại tin nhắn 1 = văn bản 2 = biểu tượng cảm xúc 3 = hình ảnh 4 = ghi âm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử hội thoại CSKH với người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_service_record`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_record` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `user_id` int(10) NOT NULL DEFAULT '0' COMMENT 'uid của người gửi',
  `to_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid của người nhận',
  `nickname` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Biệt danh người dùng',
  `avatar` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện người dùng',
  `is_tourist` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải khách hay không',
  `online` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có đang online không',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = pc, 1=WeChat, 2=Mini Program, 3=H5',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `update_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  `mssage_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Số lượng tin nhắn',
  `message` text COLLATE utf8_unicode_ci COMMENT 'Nội dung',
  `message_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại thông báo',
  PRIMARY KEY (`id`),
  KEY `to_uid` (`to_uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử người dùng chat với CSKH';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_store_service_speechcraft`
--

CREATE TABLE IF NOT EXISTS `eb_store_service_speechcraft` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `kefu_id` int(10) NOT NULL DEFAULT '0' COMMENT '0 là kịch bản chung (toàn cục)',
  `cate_id` int(10) NOT NULL DEFAULT '0' COMMENT '0 là kịch bản chung không phân loại',
  `title` varchar(100) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Tiêu đề câu trả lời mẫu',
  `message` varchar(255) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'Nội dung câu trả lời mẫu',
  `sort` int(10) NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `kefu_id` (`kefu_id`),
  KEY `cate_id` (`cate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Câu trả lời mẫu CSKH';

