  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID sản phẩm',
  `product_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại sản phẩm',
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID danh mục sản phẩm',
  `type` char(50) NOT NULL DEFAULT '' COMMENT 'Loại sản phẩm',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `count` int(11) NOT NULL DEFAULT '0' COMMENT 'Số lần truy cập',
