--
-- Cấu trúc bảng `eb_system_admin`
--

CREATE TABLE IF NOT EXISTS `eb_system_admin` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bảng quản trị viên',
  `account` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tài khoản quản trị viên',
  `head_pic` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện quản trị viên',
  `pwd` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mật khẩu quản trị viên',
  `real_name` varchar(16) NOT NULL DEFAULT '' COMMENT 'Họ tên quản trị viên',
  `roles` varchar(128) NOT NULL DEFAULT '' COMMENT 'Quyền quản trị viên (menus_id)',
  `last_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'IP đăng nhập gần nhất của quản trị viên',
  `last_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian đăng nhập gần nhất của quản trị viên',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm quản trị viên',
  `login_count` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần đăng nhập',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Cấp bậc quản trị viên',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái quản trị viên 1 hiệu lực 0 không hiệu lực',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý khu vực',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `account` (`account`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản trị viên';

