--
-- Cấu trúc bảng `eb_system_attachment`
--

CREATE TABLE IF NOT EXISTS `eb_system_attachment` (
  `att_id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên tệp đính kèm',
  `att_dir` varchar(200) NOT NULL DEFAULT '' COMMENT 'Đường dẫn tệp đính kèm',
  `satt_dir` varchar(200) NOT NULL DEFAULT '' COMMENT 'Đường dẫn ảnh nén',
  `att_size` char(30) NOT NULL DEFAULT '' COMMENT 'Kích thước tệp đính kèm',
  `att_type` char(30) NOT NULL DEFAULT '' COMMENT 'Loại tệp đính kèm',
  `pid` int(10) NOT NULL DEFAULT '0' COMMENT 'ID danh mục 0 trình soạn thảo, 1 ảnh sản phẩm, 2 ảnh mua chung, 3 ảnh săn giảm giá, 4 ảnh flash sale, 5 ảnh bài viết, 6 ảnh dữ liệu tổ hợp',
  `time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian tải lên',
  `image_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Loại lưu trữ ảnh tải lên 1=cục bộ, 2=Qiniu Cloud, 3=OSS, 4=COS ',
  `module_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Loại mô-đun tải ảnh lên 1=tải lên từ trang quản trị, 2=người dùng tạo',
  `real_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên file gốc',
  `scan_token` varchar(32) NOT NULL DEFAULT '' COMMENT 'Token tải lên khi quét mã',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại, 0 hình ảnh, 1 video',
  PRIMARY KEY (`att_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý tệp đính kèm';

