  `input_type` varchar(20) NOT NULL DEFAULT 'input' COMMENT 'Loại biểu mẫu',
  `config_tab_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID danh mục cấu hình',
