  `upload_type` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Định dạng tệp tải lên 1=một ảnh, 2=nhiều ảnh, 3=tệp',
  `required` varchar(255) NOT NULL DEFAULT '' COMMENT 'Quy tắc',
