  `high` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Chiều cao ô văn bản nhiều dòng',
  `value` varchar(5000) NOT NULL DEFAULT '' COMMENT 'Giá trị mặc định',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên cấu hình',
  `desc` varchar(500) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn cấu hình',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có ẩn không',
  `level` int(11) NOT NULL DEFAULT '0' COMMENT 'Cấp cấu hình 0 cấp cao nhất 1 cấp phụ',
  `link_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cấu hình cấp cha liên kết',
  `link_value` int(11) NOT NULL DEFAULT '0' COMMENT 'Giá trị của cấu hình cấp cha liên kết',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=435 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng cấu hình';

