  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID quản trị viên',
  `admin_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Họ tên quản trị viên',
  `path` varchar(128) NOT NULL DEFAULT '' COMMENT 'Liên kết',
  `page` varchar(64) NOT NULL DEFAULT '' COMMENT 'Hành động',
  `method` varchar(12) NOT NULL DEFAULT '' COMMENT 'Loại truy cập',
  `ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'IP đăng nhập',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thao tác',
  `merchant_id` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `admin_id` (`admin_id`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử thao tác của quản trị viên';

