--
-- Cấu trúc bảng `eb_system_menus`
--

CREATE TABLE IF NOT EXISTS `eb_system_menus` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID menu',
  `pid` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID cấp cha',
  `icon` varchar(16) NOT NULL DEFAULT '' COMMENT 'Biểu tượng',
  `menu_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên nút',
  `module` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'Tên module',
  `controller` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'Controller',
  `action` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'Tên phương thức',
  `api_url` varchar(100) NOT NULL DEFAULT '' COMMENT 'Địa chỉ API',
  `methods` varchar(10) NOT NULL DEFAULT '' COMMENT 'Phương thức gửi POST GET PUT DELETE',
  `params` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '[]' COMMENT 'Tham số',
  `sort` tinyint(3) NOT NULL DEFAULT '1' COMMENT 'Thứ tự sắp xếp',
  `is_show` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Có phải menu ẩn hay không 0 = menu ẩn, 1 = menu hiển thị',
  `is_show_path` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải menu ẩn dùng cho front-end hay không',
  `access` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Quản trị viên phụ có khả dụng hay không',
  `menu_path` varchar(128) NOT NULL DEFAULT '' COMMENT 'Tên route, dùng cho front-end',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn',
  `auth_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải menu hay không 1 menu 2 chức năng',
  `header` varchar(50) NOT NULL DEFAULT '' COMMENT 'Định danh menu trên cùng',
  `is_header` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải menu trên cùng hay không 1 có 0 không',
  `unique_auth` varchar(150) NOT NULL DEFAULT '' COMMENT 'Định danh duy nhất ở front-end',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `mark` varchar(500) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `is_show` (`is_show`) USING BTREE,
  KEY `access` (`access`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2473 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng menu';

