--
-- Cấu trúc bảng `eb_system_notification`
--

CREATE TABLE IF NOT EXISTS `eb_system_notification` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `mark` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã định danh',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Loại thông báo',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mô tả tình huống thông báo',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông báo nội bộ (0: không tồn tại, 1: bật, 2: tắt)',
  `system_title` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tiêu đề thông báo nội bộ',
  `system_text` varchar(512) NOT NULL DEFAULT '' COMMENT 'ID tin nhắn hệ thống',
  `is_wechat` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tin nhắn mẫu OA WeChat (0: không tồn tại, 1: bật, 2: tắt)',
  `wechat_tempkey` varchar(255) NOT NULL DEFAULT '' COMMENT 'tempkey tin nhắn mẫu',
  `wechat_content` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nội dung tin nhắn mẫu',
  `wechat_kid` varchar(255) NOT NULL DEFAULT '' COMMENT 'kid tin nhắn mẫu',
  `wechat_tempid` varchar(255) NOT NULL DEFAULT '' COMMENT 'tempid tin nhắn mẫu',
  `wechat_data` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tham số tin nhắn mẫu',
  `wechat_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Link tin nhắn mẫu',
  `wechat_to_routine` int(1) NOT NULL DEFAULT '0' COMMENT 'Tin nhắn mẫu chuyển đến Mini Program',
  `is_routine` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Tin nhắn đăng ký Mini Program (0: không tồn tại, 1: bật, 2: tắt)',
  `routine_tempkey` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID tin nhắn đăng ký',
  `routine_content` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nội dung tin nhắn đăng ký',
  `routine_kid` varchar(255) NOT NULL DEFAULT '' COMMENT 'kid tin nhắn đăng ký',
  `routine_tempid` varchar(255) NOT NULL DEFAULT '' COMMENT 'tempid tin nhắn đăng ký',
  `routine_data` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tham số tin nhắn đăng ký',
  `routine_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Link tin nhắn đăng ký',
  `is_sms` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Gửi SMS (0: không tồn tại, 1: bật, 2: tắt)',
  `sms_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'ID SMS',
  `sms_text` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nội dung mẫu SMS',
  `is_ent_wechat` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông báo nhóm WeCom (0: không tồn tại, 1: bật, 2: tắt)',
  `ent_wechat_text` varchar(512) NOT NULL DEFAULT '' COMMENT 'Tin nhắn WeCom',
  `url` varchar(512) NOT NULL DEFAULT '' COMMENT 'Link bot nhóm',
  `is_app` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Push APP (0: không tồn tại, 1: bật, 2: tắt)',
  `app_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID push app',
  `variable` varchar(256) NOT NULL DEFAULT '' COMMENT 'Biến',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại (1: người dùng, 2: quản trị viên)',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `custom_trigger` varchar(255) NOT NULL DEFAULT '' COMMENT 'Vị trí kích hoạt tin nhắn tùy chỉnh',
  `custom_variable` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Biến tin nhắn tùy chỉnh',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COMMENT='Cài đặt thông báo';

