--
-- Cấu trúc bảng `eb_system_pem`
--

CREATE TABLE IF NOT EXISTS `eb_system_pem` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Loại chứng chỉ',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chứng chỉ',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên file chứng chỉ',
  `content` text COMMENT 'Nội dung chứng chỉ',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng chứng chỉ';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_role`
--

CREATE TABLE IF NOT EXISTS `eb_system_role` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID quản lý vai trò',
  `role_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tên quản lý vai trò',
  `rules` text COMMENT 'Quyền quản lý vai trò (menus_id)',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cấp bậc quản trị viên',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý vai trò';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_route`
--

CREATE TABLE IF NOT EXISTS `eb_system_route` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Danh mục',
  `app_name` varchar(20) NOT NULL DEFAULT 'api' COMMENT 'Tên ứng dụng',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên route',
  `describe` text NOT NULL COMMENT 'Mô tả chức năng',
  `path` varchar(100) NOT NULL DEFAULT '' COMMENT 'Đường dẫn route',
  `method` enum('POST','GET','DELETE','PUT','*') NOT NULL DEFAULT 'GET' COMMENT 'Phương thức request của route',
  `file_path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn tệp',
  `action` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên phương thức',
  `query` longtext NOT NULL COMMENT 'Tham số request get',
  `header` longtext NOT NULL COMMENT 'header',
  `request` longtext NOT NULL COMMENT 'Dữ liệu yêu cầu',
  `request_type` varchar(100) NOT NULL DEFAULT '' COMMENT 'Loại request',
  `response` longtext NOT NULL COMMENT 'Dữ liệu trả về',
  `request_example` longtext NOT NULL COMMENT 'Ví dụ request',
  `response_example` longtext NOT NULL COMMENT 'Ví dụ dữ liệu trả về',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại',
  `add_time` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT 'Thời gian thêm',
  `delete_time` timestamp NULL DEFAULT NULL COMMENT 'Xóa trường',
  `error_code` longtext NOT NULL COMMENT 'Mã lỗi',
  PRIMARY KEY (`id`),
  KEY `path` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=1695 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quy tắc route';

--
-- Chuyển lưu dữ liệu trong bảng `eb_system_route`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_route_cate`
--

CREATE TABLE IF NOT EXISTS `eb_system_route_cate` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cha',
  `app_name` varchar(20) NOT NULL DEFAULT '' COMMENT 'Tên ứng dụng',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT 'Tên',
  `mark` varchar(32) NOT NULL DEFAULT '' COMMENT 'Định danh nhóm',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn',
  `sort` int(11) NOT NULL DEFAULT '0',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `app_name` (`app_name`)
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng danh mục quy tắc route';

