--
-- Cấu trúc bảng `eb_system_sign_reward`
--

CREATE TABLE IF NOT EXISTS `eb_system_sign_reward` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại, 0 thưởng điểm danh liên tục, 1 thưởng điểm danh tích lũy',
  `days` int(11) NOT NULL DEFAULT '0' COMMENT 'Số ngày',
  `point` int(11) NOT NULL DEFAULT '0' COMMENT 'Tặng điểm thưởng',
  `exp` int(11) NOT NULL DEFAULT '0' COMMENT 'Tặng điểm kinh nghiệm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thưởng điểm danh hệ thống';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_storage`
--

CREATE TABLE IF NOT EXISTS `eb_system_storage` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `access_key` varchar(100) NOT NULL DEFAULT '' COMMENT 'access_key',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = lưu trữ local, 2 = Qiniu, 3 = oss, 4 = cos',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên space',
  `region` varchar(100) NOT NULL DEFAULT '' COMMENT 'Khu vực',
  `acl` enum('private','public-read','public-read-write') NOT NULL DEFAULT 'public-read' COMMENT 'Quyền',
  `domain` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên miền không gian lưu trữ',
  `cdn` varchar(255) NOT NULL DEFAULT '' COMMENT 'Domain tăng tốc CDN',
  `cname` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giá trị CNAME',
  `is_ssl` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=http,1=https',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL COMMENT 'Thêm sự kiện',
  `update_time` int(10) NOT NULL COMMENT 'Sự kiện cập nhật',
  PRIMARY KEY (`id`),
  KEY `is_delete` (`is_delete`),
  KEY `status` (`status`),
  KEY `access_key` (`access_key`,`type`,`is_delete`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Lưu trữ đám mây';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_store`
--

CREATE TABLE IF NOT EXISTS `eb_system_store` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên cửa hàng',
  `introduction` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn',
  `phone` char(25) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh/thành phố/quận huyện',
  `detailed_address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Logo cửa hàng',
  `oblong_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đề xuất cửa hàng',
  `latitude` char(25) NOT NULL DEFAULT '' COMMENT 'Vĩ độ',
  `longitude` char(25) NOT NULL DEFAULT '' COMMENT 'Kinh độ',
  `valid_time` varchar(100) NOT NULL DEFAULT '' COMMENT 'Thời hạn hiệu lực xác nhận sử dụng',
  `day_time` varchar(100) NOT NULL DEFAULT '' COMMENT 'Giờ mở/đóng cửa hằng ngày',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Hiển thị',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Nhận tại cửa hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_store_staff`
--

CREATE TABLE IF NOT EXISTS `eb_system_store_staff` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng WeChat',
  `avatar` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện nhân viên cửa hàng',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID cửa hàng',
  `staff_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên nhân viên cửa hàng',
  `phone` char(15) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `verify_status` tinyint(2) NOT NULL DEFAULT '0' COMMENT 'Cho phép xác nhận sử dụng',
  `status` tinyint(2) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nhân viên cửa hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_timer`
--

CREATE TABLE IF NOT EXISTS `eb_system_timer` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên bộ đếm giờ',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Nhãn',
  `content` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái chu kỳ 1 = cứ bao nhiêu giây 2 = cứ bao nhiêu phút 3 = cứ bao nhiêu giờ 4 = cứ bao nhiêu ngày 5 = mỗi ngày chạy lúc mấy giờ 6 = mỗi tuần vào thứ mấy, giờ nào chạy 7 = mỗi tháng vào ngày mấy, giờ nào chạy',
  `month` int(11) NOT NULL DEFAULT '0' COMMENT 'Tháng',
  `week` int(11) NOT NULL DEFAULT '0' COMMENT 'Tuần',
  `day` int(11) NOT NULL DEFAULT '0' COMMENT 'CN',
  `hour` int(11) NOT NULL DEFAULT '0' COMMENT 'giờ',
  `minute` int(11) NOT NULL DEFAULT '0' COMMENT 'phút',
  `second` int(11) NOT NULL DEFAULT '0' COMMENT 'giây',
  `last_execution_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian chạy lần trước',
  `next_execution_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian chạy lần tiếp theo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian sửa',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Bật',
  `customCode` text NOT NULL COMMENT 'Code thực thi',
  `timeStr` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã thời gian',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='Bộ đếm thời gian (timer)';

--
-- Chuyển lưu dữ liệu trong bảng `eb_system_timer`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_user_level`
--

CREATE TABLE IF NOT EXISTS `eb_system_user_level` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên gói thành viên',
  `money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền mua',
  `valid_date` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hiệu lực',
  `is_forever` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải thành viên vĩnh viễn không',
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có mua không, 1=mua, 0=không mua',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có hiện không 1=hiện, 0=ẩn',
  `grade` int(11) NOT NULL DEFAULT '0' COMMENT 'Hạng thành viên',
  `discount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Chiết khấu được hưởng',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Hình nền thẻ thành viên',
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biểu tượng thành viên',
  `explain` text COMMENT 'Mô tả',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có xóa không. 1=đã xóa, 0=chưa xóa',
  `exp_num` int(10) NOT NULL DEFAULT '0' COMMENT 'Điểm kinh nghiệm lên hạng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thiết lập hạng người dùng';

--
-- Chuyển lưu dữ liệu trong bảng `eb_system_user_level`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_theme`
--

CREATE TABLE IF NOT EXISTS `eb_theme` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `version` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số phiên bản',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên chủ đề',
  `info` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mô tả ngắn của chủ đề',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại chủ đề, 0: chủ đề tự tạo, 1: chủ đề từ kho',
  `home_data` longtext COMMENT 'Dữ liệu trang chủ',
  `home_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh trang chủ',
  `home_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nguồn dữ liệu trang chủ',
  `home_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang chủ',
  `category_data` longtext COMMENT 'Dữ liệu trang danh mục',
  `category_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh trang danh mục',
  `category_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nguồn dữ liệu trang danh mục',
  `category_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang danh mục',
  `detail_data` longtext COMMENT 'Dữ liệu trang chi tiết sản phẩm',
  `detail_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh trang chi tiết sản phẩm',
  `detail_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nguồn dữ liệu trang chi tiết sản phẩm',
  `detail_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang chi tiết sản phẩm',
  `user_data` longtext COMMENT 'Dữ liệu trang cá nhân',
  `user_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh trang cá nhân',
  `user_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nguồn dữ liệu trang cá nhân',
  `user_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu trang cá nhân',
  `theme_data` longtext COMMENT 'Dữ liệu phong cách chủ đề',
  `theme_data_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nguồn dữ liệu phong cách chủ đề',
  `theme_data_update_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật dữ liệu phong cách chủ đề',
  `home_default_data` longtext COMMENT 'Dữ liệu mặc định trang chủ',
  `home_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh mặc định trang chủ',
  `category_default_data` longtext COMMENT 'Dữ liệu mặc định trang danh mục',
  `category_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh mặc định trang danh mục',
  `detail_default_data` longtext COMMENT 'Dữ liệu mặc định trang chi tiết sản phẩm',
  `detail_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh mặc định trang chi tiết sản phẩm',
  `user_default_data` longtext COMMENT 'Dữ liệu mặc định trang cá nhân',
  `user_default_image` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ảnh mặc định trang cá nhân',
  `theme_default_data` longtext COMMENT 'Dữ liệu mặc định phong cách chủ đề',
  `page_type` varchar(255) NOT NULL DEFAULT 'theme' COMMENT 'Loại trang: theme là chủ đề, micro là trang tùy chỉnh',
  `is_use` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã sử dụng',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `up_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian cập nhật',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng chủ đề';

