-- Chuyển lưu dữ liệu trong bảng `eb_theme`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_theme_download`
--

CREATE TABLE IF NOT EXISTS `eb_theme_download` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mẫu',
  `tid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mẫu',
  `download_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian tải xuống',
  `download_url` varchar(500) NOT NULL DEFAULT '' COMMENT 'Địa chỉ tải xuống',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử tải xuống chủ đề';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_upgrade_log`
--

CREATE TABLE IF NOT EXISTS `eb_upgrade_log` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `title` varchar(120) NOT NULL DEFAULT '' COMMENT 'Giải thích tiêu đề',
  `content` text NOT NULL COMMENT 'Nội dung cập nhật',
  `first_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ nhất của số phiên bản',
  `second_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ hai của số phiên bản',
  `third_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ ba của số phiên bản',
  `fourth_version` char(3) NOT NULL DEFAULT '' COMMENT 'Chữ số thứ tư của số phiên bản',
  `error_data` text NOT NULL COMMENT 'Nội dung lỗi',
  `upgrade_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian nâng cấp',
  `package_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ backup file',
  `data_link` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ backup dữ liệu',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Lịch sử nâng cấp';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user`
--

CREATE TABLE IF NOT EXISTS `eb_user` (
  `uid` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id người dùng',
  `account` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tài khoản người dùng',
  `pwd` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mật khẩu người dùng',
  `real_name` varchar(25) NOT NULL DEFAULT '' COMMENT 'Họ tên',
  `birthday` int(11) NOT NULL DEFAULT '0' COMMENT 'Ngày sinh',
  `card_id` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số CCCD/CMND',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ghi chú của người dùng',
  `partner_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đối tác',
  `group_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhóm người dùng',
  `nickname` varchar(60) NOT NULL DEFAULT '' COMMENT 'Biệt danh người dùng',
  `avatar` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện người dùng',
  `phone` char(15) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `add_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `add_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'IP khi thêm',
  `last_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian đăng nhập gần nhất',
  `last_ip` varchar(16) NOT NULL DEFAULT '' COMMENT 'IP đăng nhập gần nhất',
  `now_money` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số dư người dùng',
  `brokerage_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoa hồng',
  `integral` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Điểm thưởng còn lại của người dùng',
  `exp` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Điểm kinh nghiệm thành viên',
  `sign_num` int(11) NOT NULL DEFAULT '0' COMMENT 'Số ngày điểm danh liên tục',
  `sign_remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái nhắc điểm danh',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 là bình thường, 0 là bị khóa',
  `level` tinyint(2) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Cấp bậc',
  `agent_level` int(10) NOT NULL DEFAULT '0' COMMENT 'Cấp độ CTV',
  `spread_open` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Có tư cách cộng tác viên không',
  `spread_uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID cộng tác viên',
  `spread_time` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian liên kết cộng tác viên',
  `user_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại người dùng',
  `is_promoter` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có phải cộng tác viên không',
  `pay_count` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Số lần mua của người dùng',
  `spread_count` int(11) NOT NULL DEFAULT '0' COMMENT 'Số người cấp dưới',
  `clean_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian xóa thành viên',
  `addres` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết',
  `adminid` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Mã quản trị viên ',
  `login_type` varchar(36) NOT NULL DEFAULT '' COMMENT 'Loại đăng nhập của người dùng, h5,wechat,routine',
  `record_phone` varchar(11) NOT NULL DEFAULT '0' COMMENT 'Số điện thoại tạm thời được ghi nhận',
  `is_money_level` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Nguồn thành viên  0: Nâng cấp khi mua sản phẩm   1: Thành viên mua bằng tiền 2: Nhận từ thẻ thành viên',
  `is_ever_level` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có phải thành viên vĩnh viễn không  0: Không phải thành viên vĩnh viễn  1: Thành viên vĩnh viễn',
  `overdue_time` bigint(20) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn thành viên',
  `uniqid` varchar(32) NOT NULL DEFAULT '' COMMENT 'Giá trị duy nhất của người dùng',
  `division_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên đại lý khu vực/đại lý',
  `division_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại đại lý: 0 Thường, 1 Đại lý khu vực, 2 Đại lý, 3 Nhân viên',
  `division_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đại lý',
  `is_division` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đại lý khu vực',
  `is_agent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đại lý',
  `is_staff` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái nhân viên',
  `division_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý khu vực',
  `agent_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID đại lý',
  `staff_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID nhân viên',
  `division_percent` int(11) NOT NULL DEFAULT '0' COMMENT 'Tỷ lệ chia hoa hồng',
  `division_change_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian sửa đại lý khu vực/đại lý/nhân viên',
  `division_end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian kết thúc đại lý khu vực/đại lý/nhân viên',
  `division_invite` int(11) NOT NULL DEFAULT '0' COMMENT 'Mã mời của đại lý',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã hủy tài khoản',
  PRIMARY KEY (`uid`) USING BTREE,
  KEY `account` (`account`) USING BTREE,
  KEY `spreaduid` (`spread_uid`) USING BTREE,
  KEY `level` (`level`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `is_promoter` (`is_promoter`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng người dùng';

