--
-- Cấu trúc bảng `eb_user_address`
--

CREATE TABLE IF NOT EXISTS `eb_user_address` (
  `id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID địa chỉ người dùng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `real_name` varchar(32) NOT NULL DEFAULT '' COMMENT 'Họ tên người nhận',
  `phone` varchar(16) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người nhận',
  `province` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người nhận hàng',
  `city` varchar(64) NOT NULL DEFAULT '' COMMENT 'Thành phố của người nhận hàng',
  `city_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Id thành phố',
  `district` varchar(64) NOT NULL DEFAULT '' COMMENT 'Quận/huyện của người nhận hàng',
  `detail` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết của người nhận hàng',
  `post_code` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Mã bưu chính',
  `longitude` varchar(16) NOT NULL DEFAULT '0' COMMENT 'Kinh độ',
  `latitude` varchar(16) NOT NULL DEFAULT '0' COMMENT 'Vĩ độ',
  `is_default` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đặt làm mặc định',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `is_default` (`is_default`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng địa chỉ người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_bill`
--

CREATE TABLE IF NOT EXISTS `eb_user_bill` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID giao dịch người dùng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Liên kết id',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi ra 1 = nhận được',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề giao dịch',
  `category` varchar(64) NOT NULL DEFAULT '' COMMENT 'Loại chi tiết',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Kiểu chi tiết',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = chờ xác nhận 1 = có hiệu lực -1 = không hiệu lực',
  `take` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = chưa nhận hàng 1 = đã nhận hàng',
  `frozen_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đóng băng điểm thưởng',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `openid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`category`,`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giao dịch người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_brokerage`
--

CREATE TABLE IF NOT EXISTS `eb_user_brokerage` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID hoa hồng người dùng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Liên kết id',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Kiểu chi tiết',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề giao dịch',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi ra 1 = nhận được',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = chờ xác nhận 1 = có hiệu lực -1 = không hiệu lực',
  `take` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = chưa nhận hàng 1 = đã nhận hàng',
  `frozen_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn đóng băng',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giao dịch chia hoa hồng người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_brokerage_frozen`
--

CREATE TABLE IF NOT EXISTS `eb_user_brokerage_frozen` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền',
  `uill_id` int(10) NOT NULL DEFAULT '0' COMMENT 'Liên kết id',
  `frozen_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn đóng băng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái hiệu lực',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `order_id` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT 'ID đơn hàng',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử đóng băng hoa hồng người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_cancel`
--

CREATE TABLE IF NOT EXISTS `eb_user_cancel` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biệt danh người dùng',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT 'Số điện thoại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian người dùng gửi đăng ký',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 duyệt, 2 từ chối',
  `up_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thao tác',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng hủy tài khoản người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_enter`
--

CREATE TABLE IF NOT EXISTS `eb_user_enter` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID đăng ký cửa hàng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng',
  `province` varchar(32) NOT NULL DEFAULT '' COMMENT 'Tỉnh của cửa hàng',
  `city` varchar(32) NOT NULL DEFAULT '' COMMENT 'Thành phố của cửa hàng',
  `district` varchar(32) NOT NULL DEFAULT '' COMMENT 'Quận/huyện của cửa hàng',
  `address` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ chi tiết cửa hàng',
  `merchant_name` varchar(256) NOT NULL DEFAULT '' COMMENT 'Tên cửa hàng',
  `link_user` varchar(32) NOT NULL DEFAULT '' COMMENT 'Người dùng liên kết',
  `link_tel` varchar(16) NOT NULL DEFAULT '' COMMENT 'Số điện thoại cửa hàng',
  `charter` varchar(512) NOT NULL DEFAULT '' COMMENT 'Chứng chỉ cửa hàng',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `apply_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian duyệt',
  `success_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian duyệt',
  `fail_message` varchar(256) NOT NULL DEFAULT '' COMMENT 'Lý do không duyệt',
  `fail_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian không duyệt',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '-1 duyệt không đạt 0 chưa duyệt 1 đã duyệt',
  `is_lock` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = bật 1 = tắt',
  `is_del` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uid` (`uid`) USING BTREE,
  KEY `province` (`province`,`city`,`district`) USING BTREE,
  KEY `is_lock` (`is_lock`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng đăng ký cửa hàng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_extract`
--

CREATE TABLE IF NOT EXISTS `eb_user_extract` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `wechat_order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'ID đơn hàng WeChat',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `real_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên',
  `user_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Họ tên người dùng',
  `extract_type` varchar(32) NOT NULL DEFAULT 'bank' COMMENT 'bank = Thẻ ngân hàng alipay = Alipay wx=WeChat',
  `bank_code` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Thẻ ngân hàng',
  `bank_address` varchar(256) NOT NULL DEFAULT '' COMMENT 'Chi nhánh mở tài khoản',
  `alipay_code` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tài khoản Alipay',
  `extract_price` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số tiền rút',
  `extract_fee` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Phí rút tiền',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Hoa hồng trước khi rút',
  `fail_msg` varchar(128) NOT NULL DEFAULT '' COMMENT 'Lý do không hợp lệ',
  `fail_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian không hiệu lực',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '-1 Không được duyệt 0 Đang duyệt 1 Đã rút tiền',
  `wechat` varchar(50) NOT NULL DEFAULT '' COMMENT 'ID WeChat',
  `qrcode_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ mã QR',
  `channel_type` VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'Nguồn rút tiền',
  `out_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã đơn phía merchant',
  `transfer_bill_no` varchar(255) NOT NULL DEFAULT '' COMMENT 'Mã chuyển khoản WeChat',
  `state` varchar(32) NOT NULL DEFAULT '' COMMENT 'Trạng thái chứng từ',
  `package_info` varchar(2000) NOT NULL DEFAULT '' COMMENT 'Thông tin package để chuyển đến trang nhận tiền',
  `fail_reason` varchar(255) NOT NULL DEFAULT '' COMMENT 'Lý do thất bại',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `extract_type` (`extract_type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `openid` (`uid`) USING BTREE,
  KEY `fail_time` (`fail_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng rút tiền người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_friends`
--

CREATE TABLE IF NOT EXISTS `eb_user_friends` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `friends_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid bạn bè',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Quan hệ bạn bè của người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_group`
--

CREATE TABLE IF NOT EXISTS `eb_user_group` (
  `id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `group_name` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tên nhóm người dùng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nhóm người dùng';

