--
-- Cấu trúc bảng `eb_user_invoice`
--

CREATE TABLE IF NOT EXISTS `eb_user_invoice` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `header_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại tiêu đề hóa đơn 1: cá nhân 2: doanh nghiệp',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại hóa đơn 1: thông thường, 2: chuyên dụng',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên (thông tin xuất hóa đơn)',
  `duty_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã số thuế',
  `drawer_phone` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại người yêu cầu xuất hóa đơn',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT 'Email nhận hóa đơn',
  `tell` varchar(30) NOT NULL DEFAULT '' COMMENT 'Số điện thoại đăng ký',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ đăng ký',
  `bank` varchar(50) NOT NULL DEFAULT '' COMMENT 'Ngân hàng mở tài khoản khi đăng ký',
  `card_number` varchar(50) NOT NULL DEFAULT '' COMMENT 'Số thẻ ngân hàng',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đặt làm mặc định',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý hóa đơn người dùng' ROW_FORMAT=DYNAMIC;

