--
-- Cấu trúc bảng `eb_user_level`
--

CREATE TABLE IF NOT EXISTS `eb_user_level` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `level_id` int(11) NOT NULL DEFAULT '0' COMMENT 'Hạng vip',
  `grade` int(11) NOT NULL DEFAULT '0' COMMENT 'Hạng thành viên',
  `valid_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `is_forever` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Vĩnh viễn',
  `mer_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người bán',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0: cấm, 1: bình thường',
  `mark` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `remind` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã thông báo hay chưa',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có xóa hay không, 0 = chưa xóa, 1 = đã xóa',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `discount` int(11) NOT NULL DEFAULT '0' COMMENT 'Chiết khấu được hưởng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `id` (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử hạng người dùng';

