--
-- Cấu trúc bảng `eb_user_money`
--

CREATE TABLE IF NOT EXISTS `eb_user_money` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID số dư người dùng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `link_id` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Liên kết id',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT 'Kiểu chi tiết',
  `title` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tiêu đề giao dịch',
  `number` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Số liệu chi tiết',
  `balance` decimal(12,2) UNSIGNED NOT NULL DEFAULT '0.00' COMMENT 'Còn lại',
  `pm` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = chi ra 1 = nhận được',
  `mark` varchar(512) NOT NULL DEFAULT '' COMMENT 'Ghi chú',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0 = chờ xác nhận 1 = có hiệu lực -1 = không hiệu lực',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `pm` (`pm`) USING BTREE,
  KEY `type` (`type`,`link_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng giao dịch số dư người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_notice`
--

CREATE TABLE IF NOT EXISTS `eb_user_notice` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` text COMMENT 'ID người dùng nhận tin nhắn (kiểu: dữ liệu json)',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Loại thông báo tin nhắn (1: tin nhắn hệ thống; 2: thông báo người dùng)',
  `user` varchar(20) NOT NULL DEFAULT '' COMMENT 'Người gửi',
  `title` varchar(20) NOT NULL DEFAULT '' COMMENT 'Thông tin tiêu đề tin nhắn thông báo',
  `content` varchar(500) NOT NULL DEFAULT '' COMMENT 'Nội dung tin nhắn thông báo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian gửi tin nhắn thông báo',
  `is_send` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có gửi hay không (0: chưa gửi; 1: đã gửi)',
  `send_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian gửi',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng thông báo người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_notice_see`
--

CREATE TABLE IF NOT EXISTS `eb_user_notice_see` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `nid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID thông báo đã xem',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID người dùng xem thông báo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian xem thông báo',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử gửi thông báo người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_recharge`
--

CREATE TABLE IF NOT EXISTS `eb_user_recharge` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'UID người dùng nạp tiền',
  `order_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng',
  `trade_no` varchar(100) NOT NULL DEFAULT '' COMMENT 'Mã đơn hàng WeChat',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền nạp',
  `give_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền tặng khi mua',
  `recharge_type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại nạp tiền',
  `paid` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có nạp tiền hay không',
  `pay_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian thanh toán nạp tiền',
  `add_time` int(12) NOT NULL DEFAULT '0' COMMENT 'Thời gian nạp tiền',
  `refund_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Số tiền hoàn',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Định danh thiết bị/nền tảng truy cập của người dùng',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `order_id` (`order_id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `recharge_type` (`recharge_type`) USING BTREE,
  KEY `paid` (`paid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng nạp tiền người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_search`
--

CREATE TABLE IF NOT EXISTS `eb_user_search` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `keyword` varchar(255) NOT NULL DEFAULT '' COMMENT 'Từ khóa tìm kiếm',
  `vicword` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Tách từ khóa',
  `num` int(8) NOT NULL DEFAULT '1' COMMENT 'Số lần tìm kiếm',
  `result` text COMMENT 'Kết quả tìm kiếm',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Xóa',
  `add_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử tìm kiếm của người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_sign`
--

CREATE TABLE IF NOT EXISTS `eb_user_sign` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Giải thích điểm danh',
  `number` int(11) NOT NULL DEFAULT '0' COMMENT 'Điểm thưởng nhận được',
  `balance` int(11) NOT NULL DEFAULT '0' COMMENT 'Điểm thưởng còn lại',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử điểm danh';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_spread`
--

CREATE TABLE IF NOT EXISTS `eb_user_spread` (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `spread_uid` int(10) NOT NULL DEFAULT '0' COMMENT 'uid người giới thiệu',
  `spread_time` int(10) NOT NULL DEFAULT '0' COMMENT 'Thời gian giới thiệu',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`) USING BTREE,
  KEY `spread_uid` (`spread_uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quan hệ giới thiệu của người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_user_visit`
--

CREATE TABLE IF NOT EXISTS `eb_user_visit` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Đường dẫn truy cập',
  `ip` varchar(255) NOT NULL DEFAULT '' COMMENT 'IP của người dùng',
  `stay_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian ở lại trang (giây)',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian truy cập',
  `channel_type` varchar(255) NOT NULL DEFAULT '' COMMENT 'Định danh thiết bị/nền tảng truy cập của người dùng',
  `province` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người dùng',
  PRIMARY KEY (`id`),
  KEY `time` (`channel_type`,`add_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng truy cập người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_key`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_key` (
  `id` mediumint(8) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `reply_id` mediumint(8) NOT NULL DEFAULT '0' COMMENT 'ID nội dung trả lời',
  `keys` varchar(64) NOT NULL DEFAULT '' COMMENT 'Từ khóa',
  `key_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Loại trả lời, 0 là tự động trả lời của OA WeChat, 1 là tự động trả lời của chăm sóc khách hàng',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='Bảng hỗ trợ từ khóa trả lời WeChat' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_media`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_media` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID video và âm thanh WeChat',
  `type` varchar(16) NOT NULL DEFAULT '' COMMENT 'Loại trả lời',
  `path` varchar(128) NOT NULL DEFAULT '' COMMENT 'Đường dẫn tệp',
  `media_id` varchar(64) NOT NULL DEFAULT '' COMMENT 'ID do máy chủ WeChat trả về',
  `url` varchar(256) NOT NULL DEFAULT '' COMMENT 'Địa chỉ',
  `temporary` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Là vĩnh viễn hay tạm thời, 0 là vĩnh viễn, 1 là tạm thời',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`,`media_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng trả lời WeChat';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_message`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_message` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID bản ghi hành vi của người dùng',
  `openid` varchar(32) NOT NULL DEFAULT '' COMMENT 'openid của người dùng',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại thao tác',
  `result` varchar(512) NOT NULL DEFAULT '' COMMENT 'Bản ghi chi tiết thao tác',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thao tác',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `openid` (`openid`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử hành vi của người dùng';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_news_category`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_news_category` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID quản lý tin nhắn hình ảnh - văn bản',
  `cate_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên tin nhắn hình ảnh - văn bản',
  `sort` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thứ tự sắp xếp',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `new_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID bài viết',
  `add_time` varchar(255) NOT NULL DEFAULT '' COMMENT 'Thời gian thêm',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng quản lý tin nhắn hình ảnh - văn bản';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_qrcode`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên mã QR',
  `image` varchar(500) NOT NULL DEFAULT '' COMMENT 'Ảnh mã QR',
  `cate_id` int(11) NOT NULL DEFAULT '0' COMMENT 'ID danh mục',
  `label_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'ID nhãn',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại trả lời',
  `content` text COMMENT 'Nội dung trả lời',
  `data` text COMMENT 'Dữ liệu gửi',
  `follow` int(11) NOT NULL DEFAULT '0' COMMENT 'Số người theo dõi',
  `scan` int(11) NOT NULL DEFAULT '0' COMMENT 'Số người quét mã',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `continue_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời hạn hiệu lực',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Trạng thái',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng mã QR';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_qrcode_cate`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode_cate` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID khóa chính',
  `cate_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên danh mục mã kênh',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Bảng loại mã QR';

--
-- Chuyển lưu dữ liệu trong bảng `eb_wechat_qrcode_cate`
--


-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_qrcode_record`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_qrcode_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `qid` int(11) NOT NULL DEFAULT '0' COMMENT 'ID mã kênh',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'id người dùng',
  `is_follow` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Có theo dõi không',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian quét mã',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng lịch sử quét mã kênh';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_reply`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_reply` (
  `id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID trả lời từ khóa WeChat',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Loại trả lời',
  `data` text COMMENT 'Dữ liệu trả lời',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT '1' COMMENT '0=không khả dụng  1 =khả dụng',
  `hide` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Có ẩn không',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `hide` (`hide`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng trả lời từ khóa WeChat';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_wechat_user`
--

CREATE TABLE IF NOT EXISTS `eb_wechat_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID người dùng WeChat',
  `unionid` varchar(30) NOT NULL DEFAULT '' COMMENT 'Trường này chỉ xuất hiện sau khi người dùng liên kết OA WeChat với tài khoản nền tảng mở WeChat',
  `openid` varchar(255) NOT NULL DEFAULT '' COMMENT 'Định danh của người dùng, duy nhất đối với OA WeChat hiện tại',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT 'Biệt danh của người dùng',
  `headimgurl` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ảnh đại diện người dùng',
  `sex` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Giới tính của người dùng, giá trị 1 là nam, giá trị 2 là nữ, giá trị 0 là không xác định',
  `city` varchar(64) NOT NULL DEFAULT '' COMMENT 'Thành phố của người dùng',
  `language` varchar(64) NOT NULL DEFAULT '' COMMENT 'Ngôn ngữ của người dùng, tiếng Trung giản thể là zh_CN',
  `province` varchar(64) NOT NULL DEFAULT '' COMMENT 'Tỉnh của người dùng',
  `country` varchar(64) NOT NULL DEFAULT '' COMMENT 'Quốc gia của người dùng',
  `remark` varchar(256) NOT NULL DEFAULT '' COMMENT 'Ghi chú của người vận hành OA WeChat về người theo dõi, người vận hành OA WeChat có thể thêm ghi chú cho người theo dõi tại giao diện quản lý người dùng trên nền tảng OA WeChat',
  `groupid` smallint(5) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'ID nhóm của người dùng (tương thích với API nhóm người dùng cũ)',
  `tagid_list` varchar(256) NOT NULL DEFAULT '' COMMENT 'Danh sách ID nhãn được gắn cho người dùng',
  `subscribe` tinyint(3) UNSIGNED NOT NULL DEFAULT '1' COMMENT 'Đánh dấu người dùng có theo dõi OA WeChat này hay không',
  `subscribe_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian theo dõi OA WeChat',
  `add_time` int(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `second` int(11) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Người giới thiệu cấp 2',
  `user_type` varchar(32) NOT NULL DEFAULT 'wechat' COMMENT 'Loại người dùng',
  `is_complete` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Thông tin đã hoàn thiện hay chưa',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã hủy tài khoản',
  PRIMARY KEY (`id`),
  UNIQUE KEY `openid` (`openid`,`uid`) USING BTREE,
  KEY `groupid` (`groupid`) USING BTREE,
  KEY `subscribe_time` (`subscribe_time`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE,
  KEY `subscribe` (`subscribe`) USING BTREE,
  KEY `unionid` (`unionid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Bảng người dùng WeChat';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_routine_scheme`
--

CREATE TABLE IF NOT EXISTS `eb_routine_scheme` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Mã số',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên',
  `path` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ trang Mini Program',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT 'Địa chỉ liên kết đã tạo',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `expire_type` int(11) NOT NULL DEFAULT '-1' COMMENT 'Loại thời hạn',
  `expire_interval` int(11) NOT NULL DEFAULT '0' COMMENT 'Số ngày hết hạn',
  `expire_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian hết hạn',
  `is_del` int(11) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COMMENT='Liên kết ngoài Mini Program';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_system_ticket`
--

CREATE TABLE IF NOT EXISTS `eb_system_ticket` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Chọn nền tảng, 1 là Yilianyun, 2 là Feieyun',
  `print_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên máy in',
  `yly_user_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID người dùng Yilianyun',
  `yly_app_id` varchar(255) NOT NULL DEFAULT '' COMMENT 'ID ứng dụng Yilianyun',
  `yly_app_secret` varchar(255) NOT NULL DEFAULT '' COMMENT 'Khóa bí mật ứng dụng Yilianyun',
  `yly_sn` varchar(255) NOT NULL DEFAULT '' COMMENT 'Số thiết bị đầu cuối Yilianyun',
  `fey_user` varchar(255) NOT NULL DEFAULT '' COMMENT 'User Feieyun',
  `fey_ukey` varchar(255) NOT NULL DEFAULT '' COMMENT 'Ukey Feieyun',
  `fey_sn` varchar(255) NOT NULL DEFAULT '' COMMENT 'Feieyun SN',
  `times` int(11) NOT NULL DEFAULT '0' COMMENT 'Số liên in',
  `print_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Thời điểm in, 1 là sau khi thanh toán, 2 là sau khi đặt hàng',
  `print_content` LONGTEXT NULL DEFAULT NULL COMMENT 'Nội dung in',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian thêm',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái yêu cầu, 0 là tắt, 1 là bật',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Danh sách máy in hóa đơn';

-- --------------------------------------------------------

--
-- Cấu trúc bảng `eb_spread_apply`
--

CREATE TABLE IF NOT EXISTS `eb_spread_apply` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID tự tăng',
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT 'uid người dùng',
  `nickname` varchar(255) NOT NULL DEFAULT '' COMMENT 'Biệt danh người dùng',
  `real_name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Tên người dùng',
  `phone` varchar(32) NOT NULL DEFAULT '0' COMMENT 'Số điện thoại người dùng',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Trạng thái đăng ký 0 nộp đơn, 1 đồng ý, 2 từ chối',
  `add_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian đăng ký',
  `status_time` int(11) NOT NULL DEFAULT '0' COMMENT 'Thời gian duyệt',
  `content` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Nội dung tự giới thiệu',
  `refusal_reason` varchar(1000) NOT NULL DEFAULT '' COMMENT 'Lý do từ chối',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Đã xóa',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Đơn đăng ký cộng tác viên';

