INSERT INTO `eb_store_service_speechcraft` (`id`, `kefu_id`, `cate_id`, `title`, `message`, `sort`, `add_time`) VALUES
(1, 0, 0, 'Khách hàng thấy đắt, hoặc hỏi có thể giảm giá không', 'Shop không thể đưa ra mức giá thấp nhất cho bạn, nhưng shop có thể mang đến chất lượng và dịch vụ tốt nhất, shop thà giải thích về giá một lúc còn hơn phải xin lỗi về chất lượng cả đời', 0, 1664328094),
(2, 0, 0, 'Câu nói nâng tầm giá trị', 'Người ngoài nghề so giá cả, người trong nghề so giá trị, nhìn là biết bạn là người trong nghề', 0, 1664328158),
(3, 0, 0, 'Giúp khách hàng tin tưởng hơn', 'Làm ra sản phẩm có tâm luôn là tâm niệm ban đầu của chúng tôi, dịch vụ tốt cùng sản phẩm tốt, làm khách hàng hài lòng là điều chúng tôi luôn theo đuổi.', 0, 1664328199);
