INSERT INTO `eb_system_config` (`id`, `menu_name`, `type`, `input_type`, `config_tab_id`, `parameter`, `upload_type`, `required`, `width`, `high`, `value`, `info`, `desc`, `sort`, `status`, `level`, `link_id`, `link_value`) VALUES
(1, 'site_name', 'text', 'input', 1, '', 1, 'required:true', 100, 0, '\"\"', 'Tên website', 'Dùng ở trang quản trị, PC, H5, chia sẻ trang, tên website trên poster và các vị trí khác', 97, 1, 0, 0, 0),
(2, 'site_url', 'text', 'input', 1, '', 1, 'required:true,url:true', 100, 0, '\"\"', 'Địa chỉ website', 'Được cấu hình tự động khi cài đặt hệ thống; không nên tùy ý thay đổi! Việc thay đổi sẽ ảnh hưởng đến truy cập website, yêu cầu API, lưu trữ tệp cục bộ, callback thanh toán, ủy quyền WeChat, thanh toán, truy cập ảnh Mini Program, một số mã QR, xác thực bản quyền chính thức và các mục khác', 95, 1, 0, 0, 0),
(3, 'site_logo', 'upload', 'input', 122, '', 1, '', 0, 0, '\"\\/statics\\/system_images\\/admin_logo_big.png\"', 'LOGO lớn trang quản trị', 'Logo ở góc trên bên trái khi mở rộng menu, kích thước đề xuất [170*50]', 89, 1, 0, 0, 0),
(4, 'site_phone', 'text', 'input', 1, '', 0, '', 100, 0, '\"\"', 'Số điện thoại liên hệ', 'Số điện thoại liên hệ', 0, 0, 0, 0, 0),
(13, 'wechat_appid', 'text', 'input', 130, '', 1, '', 0, 0, '\"\"', 'AppID', 'AppID của OA WeChat', 99, 1, 0, 0, 0),
(14, 'wechat_appsecret', 'text', 'input', 130, '', 1, '', 0, 0, '\"\"', 'AppSecret', 'AppSecret của OA WeChat', 95, 1, 0, 0, 0),
(15, 'wechat_token', 'text', 'input', 131, '', 1, '', 0, 0, '\"\"', 'TOKEN xác thực WeChat', 'TOKEN xác thực WeChat', 88, 1, 0, 0, 0),
(16, 'wechat_encode', 'radio', 'input', 131, '0=>Chế độ không mã hóa\n1=>Chế độ tương thích\n2=>Chế độ bảo mật', 1, '', 0, 0, '0', 'Phương thức mã hóa/giải mã tin nhắn', 'Nếu cần dùng chế độ bảo mật, vui lòng thay đổi trong trung tâm quản lý, chỉ áp dụng cho tài khoản dịch vụ và tài khoản đăng ký đã xác minh', 84, 1, 0, 0, 0),
(17, 'wechat_encodingaeskey', 'text', 'input', 131, '', 1, '', 0, 0, '\"\"', 'EncodingAESKey', 'Key mã hóa/giải mã tin nhắn OA WeChat, cần điền giá trị này khi dùng chế độ bảo mật, vui lòng thay đổi trong trung tâm quản lý trước rồi điền giá trị này, chỉ hỗ trợ tài khoản dịch vụ đã xác minh', 80, 1, 0, 0, 0),
(18, 'wechat_share_img', 'upload', 'input', 70, '', 1, '', 0, 0, '\"\"', 'Ảnh chia sẻ WeChat', 'Nếu điền địa chỉ ảnh này, khi chia sẻ trang web sẽ dùng ảnh này. Giúp tránh ảnh chia sẻ bị méo, tỷ lệ ảnh 5:4, nên nhỏ hơn 50KB', 0, 1, 0, 0, 0),
(19, 'wechat_qrcode', 'upload', 'input', 130, '', 1, '', 0, 0, '\"\"', 'Mã QR theo dõi', 'Mã QR theo dõi OA WeChat hiển thị ở phần hướng dẫn theo dõi OA WeChat', 76, 1, 0, 0, 0),
(21, 'wechat_share_title', 'text', 'input', 70, '', 0, 'required:true', 100, 0, '\"\"', 'Tiêu đề chia sẻ WeChat', 'Tiêu đề chia sẻ WeChat', 0, 1, 0, 0, 0),
(22, 'wechat_share_synopsis', 'textarea', '', 70, '', 0, '', 100, 5, '\"\"', 'Mô tả chia sẻ WeChat', 'Mô tả chia sẻ WeChat', 0, 1, 0, 0, 0),
(25, 'pay_weixin_mchid', 'text', 'input', 4, '', 0, '', 100, 0, '\"\"', 'Mchid', 'Mã merchant WeChat Pay, mã merchant WeChat Pay', 0, 1, 0, 0, 0),
(26, 'pay_weixin_client_cert', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ WeChat Pay', 'Chứng chỉ WeChat Pay, có thể tải xuống trên nền tảng merchant WeChat Pay! Tên tệp thường là apiclient_cert.pem', 0, 1, 0, 0, 0),
(27, 'pay_weixin_client_key', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'Khóa chứng chỉ WeChat Pay', 'Khóa chứng chỉ WeChat Pay, có thể tải xuống trên nền tảng merchant WeChat Pay! Tên tệp thường là apiclient_key.pem', 0, 1, 0, 0, 0),
(28, 'pay_weixin_key', 'text', 'input', 4, '', 0, '', 100, 0, '\"\"', 'Key', 'Key thanh toán của merchant. Sau khi được duyệt, xem trong email do WeChat gửi.', 0, 1, 0, 0, 0),
(29, 'pay_weixin_open', 'radio', 'input', 109, '0=>Tắt\nweixin=>WeChat\nallinpay=>Allinpay', 1, '', 0, 0, '\"weixin\"', 'WeChat Pay', 'Vui lòng chọn kênh WeChat Pay, nếu tắt thì phía người dùng sẽ không hiển thị', 100, 1, 0, 0, 0),
(32, 'store_free_postage', 'text', 'number', 114, '', 1, 'number:true,min:-1', 100, 0, '\"1000000\"', 'Miễn phí vận chuyển theo giá trị đơn', 'Đơn hàng trong cửa hàng đạt mức tiền này sẽ được miễn phí vận chuyển, mục này được ưu tiên hơn các cài đặt phí vận chuyển khác', 100, 1, 0, 0, 0),
(33, 'offline_postage', 'radio', 'input', 114, '1=>Miễn phí vận chuyển\n0=>Không miễn phí vận chuyển', 1, '', 0, 0, '0', 'Miễn phí vận chuyển khi thanh toán ngoại tuyến', 'Có miễn phí vận chuyển khi người dùng chọn thanh toán ngoại tuyến hay không', 97, 1, 0, 0, 0),
(34, 'integral_ratio', 'text', 'input', 11, '', 0, 'number:true', 100, 0, '\"0.1\"', 'Khấu trừ bằng điểm thưởng', 'Tỷ lệ khấu trừ bằng điểm thưởng (1 điểm được trừ bao nhiêu tiền) đơn vị: đ', 10, 1, 0, 0, 0),
(44, 'store_user_min_recharge', 'text', 'number', 28, '', 1, 'required:true,number:true,min:0', 100, 0, '0.01', 'Số tiền nạp tối thiểu', 'Số tiền nạp tối thiểu mỗi lần của người dùng', 3, 1, 0, 0, 0),
(46, 'system_express_app_code', 'text', 'input', 92, '', 1, '', 0, 0, '\"\"', 'Khóa tra cứu vận chuyển', 'Địa chỉ mua khóa API tra cứu vận chuyển trên Alibaba Cloud Marketplace: https://market.aliyun.com/products/57126001/cmapi021863.html?spm=5176.2020520132.101.4.42a672183nvgfH#sku=yuncode1586300000', 0, 1, 0, 0, 0),
(49, 'store_brokerage_ratio', 'text', 'input', 73, '', 0, 'required:true,min:0,max:100,number:true', 100, 0, '\"0\"', 'Tỷ lệ trả hoa hồng cấp 1', 'Tỷ lệ trả hoa hồng cho người giới thiệu sau khi đơn hàng giao dịch thành công, 0 - 100, ví dụ: 5 = trả 5% giá trị sản phẩm trong đơn hàng', 5, 1, 0, 0, 0),
(53, 'user_extract_min_price', 'text', 'input', 74, '', 0, 'required:true,number:true,min:0', 100, 0, '\"1\"', 'Số tiền rút tối thiểu', 'Giới hạn số tiền rút tối thiểu của người dùng', 10, 1, 0, 0, 0),
(59, 'routine_appId', 'text', 'input', 132, '', 0, '', 100, 0, '\"\"', 'appId', 'appID Mini Program', 100, 1, 0, 0, 0),
