(473, 'get_remote_login_url', 'text', 'input', 135, '', 1, '', 100, 0, '\"\"', 'Địa chỉ đăng nhập từ xa', 'Khi liên kết chuyển đến trang h5 của cửa hàng nhúng có kèm tham số (remote_token=token tạo cho người dùng từ xa), hệ thống có thể tự động đăng nhập cửa hàng, nếu remote_token trống, hệ thống này sẽ coi như người dùng chưa đăng nhập ở hệ thống bên ngoài và chuyển đến địa chỉ này để đăng nhập', 0, 1, 0, 0, 0),
(474, 'param_filter_data', 'textarea', 'input', 137, '', 1, '', 100, 20, '\"L1wuXC4vCi9cPFw\\/LwovXGJvclxiLio9LiovaQovKHNlbGVjdFtcc1xTXSo\\/KShmcm9tfGxpbWl0KS9pCi8odW5pb25bXHNcU10qP3NlbGVjdCkvaQovKGhhdmluZ3x1cGRhdGV4bWx8ZXh0cmFjdHZhbHVlKS9pCi9zbGVlcFwoKFxzKikoXGQqKShccyopXCkvaQovYmVuY2htYXJrXCgoLiopXCwoLiopXCkvaQovYmFzZTY0X2RlY29kZVwoL2kKLyg\\\\/KD86bHN8cHdkfHdob2FtaXxsbHxpZmNvbmZpZ3xpcGNvbmZpZ3wmJnxjaG1vZHxjZHxta2RpcnxybWRpcnxjcHxtdikvaQovXHNhbmRccysuKj0uKi9p\"', 'Cấu hình WAF', 'Tham số kiểm tra trong cấu hình WAF, dùng để lọc bỏ tham số không mong muốn hoặc chặn yêu cầu, nhiều tham số thì phân tách bằng cách xuống dòng', 0, 1, 0, 0, 0),
(475, 'product_reply_examine', 'radio', 'input', 136, '1=>Cần duyệt\n0=>Không cần duyệt', 1, '', 0, 0, '1', 'Duyệt đánh giá', 'Đánh giá sản phẩm do người dùng gửi có cần duyệt ở trang quản trị không, nếu cần thì hiển thị sau khi duyệt xong, nếu không cần thì hiển thị ngay sau khi người dùng gửi', 0, 1, 0, 0, 0),
(476, 'reward_coupon', 'text', 'input', 105, '', 1, '', 100, 0, '', 'Phiếu giảm giá được tặng', 'Phiếu giảm giá được tặng', 0, 0, 0, 0, 0),
(477, 'param_filter_type', 'radio', 'input', 137, '0=>Tắt\n1=>Chặn\n2=>Lọc', 1, '', 0, 0, '2', 'Loại WAF', 'Loại WAF: Tắt (mọi tham số đều được gửi yêu cầu bình thường), Chặn (chặn yêu cầu API khi có tham số khớp với cấu hình WAF), Lọc (lọc bỏ tham số khớp với cấu hình WAF, API vẫn được gọi bình thường)', 10, 1, 0, 0, 0),
(478, 'product_type_config', 'checkbox', 'input', 136, '0=>Sản phẩm thường\n1=>Mã thẻ/Ổ đĩa mạng\n2=>Phiếu giảm giá\n3=>Sản phẩm ảo', 1, '', 0, 0, '[\"0\",\"1\",\"2\",\"3\"]', 'Cấu hình loại sản phẩm', 'Cấu hình loại sản phẩm, có thể cấu hình các loại sản phẩm được phép chọn khi thêm sản phẩm', 1, 1, 0, 0, 0),
(479, 'weixin_extract_type', 'radio', 'input', 74, '0=>Chuyển khoản ngoại tuyến thủ công\n1=>Tự động chuyển vào ví WeChat', 1, '', 0, 0, '0', 'Rút tiền qua WeChat', 'Phương thức rút tiền WeChat: chuyển khoản ngoại tuyến thủ công, tự động chuyển vào ví WeChat (cần kích hoạt tính năng merchant chuyển tiền vào ví WeChat)', 7, 1, 0, 0, 0),
(480, 'alipay_extract_type', 'radio', 'input', 74, '0=>Chuyển khoản ngoại tuyến thủ công\n1=>Tự động chuyển vào số dư Alipay', 1, '', 0, 0, '0', 'Rút tiền Alipay', 'Phương thức rút tiền Alipay: chuyển khoản ngoại tuyến thủ công, tự động chuyển vào số dư Alipay (cần kích hoạt tính năng chuyển khoản Alipay)', 6, 1, 0, 0, 0),
(481, 'v3_pay_public_key', 'text', 'input', 4, '', 1, '', 100, 0, '\"\"', 'Khóa công khai thanh toán v3', 'Khóa công khai thanh toán v3, vui lòng điền nếu phiên bản mới dùng khóa công khai', 0, 1, 0, 0, 0),
(482, 'v3_pay_public_pem', 'upload', 'input', 4, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ khóa công khai thanh toán v3', 'Chứng chỉ khóa công khai thanh toán v3, tải lên chứng chỉ này khi dùng khóa công khai thanh toán phiên bản mới', 0, 1, 0, 0, 0),
(483, 'v3_transfer_scene_id', 'text', 'input', '4', '', '1', '', '0', '0', '\"1000\"', 'Mã kịch bản rút tiền tự động WeChat', 'Mã kịch bản rút tiền tự động WeChat', 0, 1, 0, 0, 0),
(484, 'custom_admin_js', 'textarea', 'input', 123, '', 1, '', 100, 10, '\"\"', 'JS tùy chỉnh cho trang quản trị', 'JS tùy chỉnh được tải trên trang quản trị', 0, 1, 0, 0, 0),
(485, 'custom_pc_js', 'textarea', 'input', 123, '', 1, '', 100, 10, '\"\"', 'JS tùy chỉnh cho PC', 'JS tùy chỉnh được tải trên PC', 0, 1, 0, 0, 0),
(486, 'merchant_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ khóa công khai ứng dụng', 'Chứng chỉ khóa công khai ứng dụng được tải xuống sau khi hoàn tất thiết lập ký API Alipay', 0, 1, 1, 489, 1),
(487, 'alipay_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ khóa công khai Alipay', 'Chứng chỉ khóa công khai Alipay được tải xuống sau khi hoàn tất thiết lập ký API Alipay', 0, 1, 1, 489, 1),
(488, 'alipay_root_cert_path', 'upload', 'input', 63, '', 3, '', 0, 0, '\"\"', 'Chứng chỉ gốc Alipay', 'Chứng chỉ gốc Alipay được tải xuống sau khi hoàn tất thiết lập ký API Alipay', 0, 1, 1, 489, 1),
(489, 'alipay_sign_type', 'radio', 'input', 63, '0=>Khóa\n1=>Chứng chỉ', 1, '', 0, 0, '0', 'Kiểu ký API', 'Kiểu ký API: khóa hoặc chứng chỉ', 80, 1, 0, 0, 0),
(490, 'image_thumb_status', 'radio', 'input', 31, '1=>Bật\n0=>Tắt', 1, '', 0, 0, '0', 'Bật/tắt ảnh thu nhỏ', 'Có bật ảnh thu nhỏ hay không', 0, 1, 0, 0, 0);
