(1, 'verify_code', 'Mã xác thực SMS', 'Mã xác thực SMS', 0, 'Mã xác thực SMS', 'Mã xác thực của bạn là: {code}, có hiệu lực trong {time} phút. Nếu không phải bạn thực hiện, vui lòng bỏ qua tin nhắn này.', 0, '', '', '', '', 0, '', '', '', '', 1, '538393', 'Mã xác thực của bạn là: {$code}, có hiệu lực trong {$time} phút. Nếu không phải bạn thực hiện, vui lòng bỏ qua tin nhắn này.', 0, '', '', 0, 0, '', 1, 0),
(2, 'bind_spread_uid', 'Thông báo liên kết quan hệ giới thiệu', 'Thông báo liên kết quan hệ giới thiệu', 1, 'Thông báo liên kết cấp dưới', 'Chúc mừng, lại thêm một chiến tướng được liên kết vĩnh viễn vào đội của bạn, người dùng {nickname} đã gia nhập đội ngũ của bạn!', 0, '', '', '', '', 0, '', '', '', '', 0, '', '', 0, '', '', 0, 0, '{nikename} Tên người dùng', 1, 0),
(3, 'order_pay_success', 'Thông báo thanh toán thành công', 'Thông báo thanh toán thành công', 1, 'Thông báo mua hàng thành công', 'Sản phẩm bạn mua đã được thanh toán thành công, số tiền thanh toán {pay_price}đ, mã đơn hàng {order_id}, cảm ơn bạn đã mua hàng!', 1, '43216', 'Mã đơn hàng: {{character_string2.DATA}}\nThời gian đặt hàng: {{time4.DATA}}\nTên sản phẩm: {{thing3.DATA}}\nSố tiền thanh toán: {{amount5.DATA}}', '', '', 1, '1927', 'Mã thanh toán: {{character_string1.DATA}}\nSố tiền thanh toán: {{amount2.DATA}}\nThời gian thanh toán: {{date3.DATA}}', '', '', 1, '520268', 'Sản phẩm bạn mua đã được thanh toán thành công, số tiền thanh toán {$pay_price}đ, mã đơn hàng {$order_id}, cảm ơn bạn đã mua hàng!', 0, '', '', 0, 0, '{order_id} Mã đơn hàng, {total_num} Tổng số sản phẩm, {pay_price} Số tiền thanh toán', 1, 0),
(4, 'order_postage_success', 'Thông báo giao hàng', 'Thông báo giao hàng', 1, 'Thông báo giao hàng', 'Chào bạn {nickname}, sản phẩm {store_name} của bạn thuộc đơn hàng {order_id} đã được gửi đi, vui lòng chú ý nhận hàng', 1, '42984', 'Mã đơn hàng: {{character_string2.DATA}}\nThời gian giao hàng: {{time12.DATA}}\nTên sản phẩm: {{thing4.DATA}}\nĐơn vị vận chuyển: {{thing13.DATA}}\nMã vận đơn: {{character_string14.DATA}}', '', '', 1, '1458', 'Mã vận đơn: {{character_string2.DATA}}\nĐơn vị vận chuyển: {{thing1.DATA}}\nThời gian giao hàng: {{time3.DATA}}\nSản phẩm trong đơn: {{thing5.DATA}}', '', '', 1, '520269', 'Chào bạn {$nickname}, sản phẩm {$store_name} của bạn thuộc đơn hàng {$order_id} đã được gửi đi, vui lòng chú ý nhận hàng', 0, '', '', 0, 0, '{nickname} Biệt danh người dùng, {store_name} Tên sản phẩm, {order_id} Mã đơn hàng, {delivery_name} Tên đơn vị vận chuyển, {delivery_id} Mã vận đơn, {user_address} Địa chỉ nhận hàng', 1, 0),
(5, 'order_deliver_success', 'Thông báo giao hàng tận nơi', 'Thông báo giao hàng tận nơi', 1, 'Thông báo giao hàng', 'Chào bạn {nickname}, sản phẩm {store_name} của bạn thuộc đơn hàng {order_id} đã được gửi đi, vui lòng chú ý nhận hàng', 1, '50079', 'Mã đơn hàng: {{character_string1.DATA}}\nThời gian giao hàng: {{time8.DATA}}\nTên sản phẩm: {{thing5.DATA}}\nNhân viên giao hàng: {{thing9.DATA}}\nSố điện thoại nhân viên giao hàng: {{phone_number10.DATA}}', '', '', 1, '1128', 'Thông tin sản phẩm: {{thing8.DATA}}\r\nMã đơn hàng: {{character_string1.DATA}}\r\nNgười giao hàng: {{name4.DATA}}\r\nSố điện thoại nhân viên giao hàng: {{phone_number10.DATA}}', '', '', 1, '520269', 'Chào bạn {$nickname}, sản phẩm {$store_name} của bạn thuộc đơn hàng {$order_id} đã được gửi đi, vui lòng chú ý nhận hàng', 0, '', '', 0, 0, '{nickname} Biệt danh người dùng, {store_name} Tên sản phẩm, {order_id} Mã đơn hàng, {delivery_name} Họ tên nhân viên giao hàng, {delivery_id} Số điện thoại nhân viên giao hàng, {user_address} Địa chỉ nhận hàng', 1, 0),
(6, 'order_take', 'Thông báo xác nhận đã nhận hàng', 'Thông báo xác nhận đã nhận hàng', 1, 'Thông báo xác nhận đã nhận hàng', 'Bạn ơi, đơn hàng {order_id}, sản phẩm {store_name} đã được xác nhận nhận hàng, cảm ơn bạn đã mua hàng!', 1, '42985', 'Mã đơn hàng: {{character_string2.DATA}}\nThời gian ký nhận: {{character_string7.DATA}}\nTên sản phẩm: {{thing4.DATA}}\nSố tiền đơn hàng: {{amount9.DATA}}', '', '', 1, '1481', 'Loại đơn hàng: {{thing1.DATA}}\nSản phẩm trong đơn: {{thing2.DATA}}\nThời gian nhận hàng: {{date5.DATA}}', '', '', 1, '520271', 'Bạn ơi, đơn hàng {$order_id}, sản phẩm {$store_name} đã được xác nhận nhận hàng, cảm ơn bạn đã mua hàng!', 0, '', '', 0, 0, '{order_id} Mã đơn hàng, {store_name} Tên sản phẩm', 1, 0),
(7, 'order_refund', 'Thông báo hoàn tiền thành công', 'Thông báo hoàn tiền thành công', 1, 'Thông báo hoàn tiền thành công', 'Đơn hàng {order_id} của bạn đã được đồng ý hoàn tiền, số tiền hoàn {refund_price}đ.', 1, '46622', 'Mã đơn hàng: {{character_string1.DATA}}\nThời gian hoàn tiền: {{time5.DATA}}\nTên sản phẩm: {{thing2.DATA}}\nSố tiền hoàn: {{amount3.DATA}}', '', '', 1, '1451', 'Trạng thái hoàn tiền: {{thing1.DATA}}\nSản phẩm hoàn tiền: {{thing2.DATA}}\nSố tiền hoàn: {{amount3.DATA}}\nMã hoàn tiền: {{character_string6.DATA}}', '', '', 1, '979010', 'Đơn hàng {$order_id} của bạn đã được đồng ý hoàn tiền, số tiền hoàn {$refund_price}đ.', 0, '', '', 0, 0, '{order_id} Mã đơn hàng, {refund_price} Số tiền hoàn, {pay_price} Số tiền đơn hàng', 1, 0),
